// Auto-generated — regenerate with: loft scripts/build-playground-examples.loft
export const EXAMPLES = {
"ex_collections": "// collections.loft — vector + hash side-by-side.\n//\n// Demonstrates: `vector<T>` literals + iteration, `hash<T[key]>`\n// lookup, and the same records held in both views.  The empty\n// collection literal is `[]` (NOT `{}` — that is an empty block).\n//\n// The hash key (`text`) must be UNIQUE across the records — a hash holds\n// one record per key, so feed it distinct keys.\n\nstruct Word {\n  text: text,\n  count: integer,\n}\n\nstruct Counter {\n  // A vector preserves insertion order.\n  ordered: vector<Word>,\n  // A hash gives O(1) lookup by the `text` field.\n  by_text: hash<Word[text]>,\n}\n\nfn main() {\n  c = Counter { ordered: [], by_text: [] };\n  // Add three words with distinct keys.  ONE append is enough: the two fields are a\n  // linked group — two collections over the same element type are two routes to a single\n  // record set — so appending to `ordered` puts the record in `by_text` too.  Appending to\n  // both would add each word TWICE, and the vector is the only member that shows it (the\n  // hash keeps one entry per key whichever way round).\n  for w in [Word { text: \"apple\", count: 3 },\n            Word { text: \"banana\", count: 5 },\n            Word { text: \"cherry\", count: 2 }] {\n    c.ordered += [w];\n  }\n  // Vector iteration walks in insertion order.\n  print(\"In insertion order:\\n\");\n  for entry in c.ordered {\n    print(\"  {entry.text} (count {entry.count})\\n\");\n  }\n  // Hash lookup is by key — `by_text[\"banana\"]` is O(1).\n  print(\"Hash lookup of 'banana': count {c.by_text[\\\"banana\\\"].count}\\n\");\n}",
"ex_fibonacci": "// fibonacci.loft — recursive and iterative fibonacci side-by-side.\n//\n// Demonstrates: function declarations, recursion, while loops, and\n// the `assert` builtin (used here to confirm both definitions agree).\n\nfn fib_recursive(n: integer) -> integer {\n  if n < 2 { n } else { fib_recursive(n - 1) + fib_recursive(n - 2) }\n}\n\nfn fib_iterative(n: integer) -> integer {\n  a = 0;\n  b = 1;\n  i = 0;\n  while i < n {\n    next = a + b;\n    a = b;\n    b = next;\n    i += 1;\n  }\n  a\n}\n\nfn main() {\n  // Print the first ten Fibonacci numbers.\n  i = 0;\n  while i < 10 {\n    print(\"{fib_iterative(i)} \");\n    i += 1;\n  }\n  print(\"\\n\");\n  // Cross-check: the two definitions agree on small inputs.\n  i = 0;\n  while i < 10 {\n    assert(fib_recursive(i) == fib_iterative(i), \"fib mismatch at {i}\");\n    i += 1;\n  }\n}",
"ex_files": "// files.loft — write a text file, read it back, count its lines.\n//\n// Demonstrates: file I/O via the `file()` constructor + method-style\n// `f.write(...)` and `f.content()`.  See STDLIB.md for the full API.\n//\n// The example is hermetic — it writes into the system temporary\n// directory and prints the contents back.\n\nfn main() {\n  // `temp_dir()` rather than a literal \"/tmp\": the temporary directory\n  // differs by platform, and this bundle ships to Windows too.\n  path = \"{temp_dir() ?? \".\"}/loft_example_files.txt\";\n  // `file(path)` returns a File handle even if the path doesn't\n  // exist yet; the first `write` creates it.\n  out = file(path);\n  out.write(\"first line\\nsecond line\\nthird line\\n\");\n  // Re-open to read the contents.\n  contents = file(path).content() ?? \"\";\n  // Count newlines for the line count.\n  line_count = 0;\n  for ch in contents {\n    if ch == '\\n' { line_count += 1; }\n  }\n  print(\"Wrote {len(contents)} bytes, {line_count} lines, to {path}\\n\");\n  // Show what we read.\n  print(\"---\\n\");\n  print(contents);\n  print(\"---\\n\");\n}",
"ex_fizzbuzz": "// fizzbuzz.loft — the classic interview puzzle.\n//\n// For each number from 1 to 20: print \"Fizz\" if divisible by 3,\n// \"Buzz\" if divisible by 5, \"FizzBuzz\" if divisible by both, and\n// the number otherwise.\n//\n// Demonstrates: `for x in 1..=N` range iteration, `if`/`else if`\n// chains, the `%` modulo operator, string interpolation.\n\nfn main() {\n  for n in 1..=20 {\n    if n % 15 == 0 {\n      print(\"FizzBuzz\\n\");\n    } else if n % 3 == 0 {\n      print(\"Fizz\\n\");\n    } else if n % 5 == 0 {\n      print(\"Buzz\\n\");\n    } else {\n      print(\"{n}\\n\");\n    }\n  }\n}",
"ex_hello": "// hello.loft — the canonical first program.\n//\n// This whole file IS the program.  A `.loft` file with loose statements is a\n// SCRIPT: no `fn main`, no `;` needed between top-level statements, and they\n// run once, top to bottom.  Add a `fn main` when you want an explicit entry\n// point — both shapes are compiled the same way after that.\n//\n// Loft has no `let`, no `var`, no type annotations on locals.  You assign a\n// value and the compiler infers the type for you.  String interpolation uses\n// braces: `\"Hello, {name}!\"` substitutes the variable.  `print` writes without\n// a trailing newline.\n\nname = \"world\"\nprint(\"Hello, {name}!\\n\")",
"ex_match": "// match.loft — pattern matching on enums.\n//\n// Demonstrates: plain enums, struct-enum variants (each variant\n// carries its own fields), `match` exhaustiveness, method dispatch\n// across variants.\n\nenum Shape {\n  Circle { radius: float },\n  Rect   { width: float, height: float },\n  Square { side: float },\n}\n\nfn area(self: Shape) -> float {\n  match self {\n    Circle { radius } => 3.14159 * radius * radius,\n    Rect   { width, height } => width * height,\n    Square { side } => side * side,\n  }\n}\n\nfn main() {\n  shapes = [\n    Circle { radius: 1.0 },\n    Rect   { width: 2.0, height: 3.0 },\n    Square { side: 4.0 },\n  ];\n  for s in shapes {\n    a = s.area();\n    match s {\n      Circle { radius } => print(\"Circle r={radius} area={a}\\n\"),\n      Rect   { width, height } => print(\"Rect {width}x{height} area={a}\\n\"),\n      Square { side } => print(\"Square {side}x{side} area={a}\\n\"),\n    }\n  }\n}",
"ex_structs": "// structs.loft — defining a Point struct and computing distances.\n//\n// Demonstrates: struct declarations, field access, methods (functions\n// whose first parameter is named `self`), float arithmetic.\n\nstruct Point {\n  x: float,\n  y: float,\n}\n\nfn distance(self: Point, other: Point) -> float {\n  dx = self.x - other.x;\n  dy = self.y - other.y;\n  sqrt(dx * dx + dy * dy)\n}\n\nfn main() {\n  origin = Point { x: 0.0, y: 0.0 };\n  target = Point { x: 3.0, y: 4.0 };\n  // Method-style call: `origin.distance(target)` is the same as\n  // `distance(origin, target)` — Loft picks up the receiver from the\n  // dot syntax.\n  d = origin.distance(target);\n  print(\"distance from ({origin.x}, {origin.y}) to ({target.x}, {target.y}) = {d}\\n\");\n}",
"loft_language": "// Welcome to Loft! Loft is a concise, statically-typed language designed to be\n// safe and easy to embed in larger Rust projects. It is great for scripting\n// game logic, configuration, data transformations, and anywhere you want a\n// friendly language backed by a fast Rust runtime.\n//\n// These documentation pages are your guided tour — each page is also a live\n// test, so every example you see has already been verified to work exactly as\n// shown. The best way to get started is to read the pages in order. This first\n// page introduces the handful of ideas that shape every other part of the\n// language.\n// ## No type declarations for local variables\n// Loft figures out the type of a variable from what you assign to it.\n// You never write 'let x: integer = 5' — just write 'x = 5' and move on.\n// The compiler still checks types strictly; it just does the bookkeeping for you.\n// If you assign the wrong type later, you get a clear compile error, not a crash.\n// ## Implicit return\n// The last expression in a function body is automatically its return value.\n// Short helper functions need no 'return' statement, which keeps them clean.\n// You can still write 'return value;' to exit early from the middle of a function.\n// ## Null is visible, not hidden\n// Any value can be null unless you explicitly mark it otherwise.\n// Null means \"no value\" — like a missing search result or a failed conversion.\n// A null value behaves like false in a condition, so you can test for it with '!'.\n// There is no NullPointerException waiting to surprise you: null is just false.\n// ## Text is UTF-8\n// Text in Loft is stored as UTF-8, the same encoding used on the web.\n// 'len()' counts bytes, not visible characters.\n// Be mindful of multi-byte characters like emoji when slicing text by position.\n// Everything from ASCII to emoji to Chinese characters works correctly.\n// ## Collections share their records\n// Vectors, sorted trees, and hash maps are not separate silos.\n// They share their underlying storage and can be combined inside a single struct,\n// so you can index the same data in multiple ways without copying anything.\n// For example, a word-frequency counter can keep a vector (insertion order) and\n// a hash (fast name lookup) pointing at the same records simultaneously.\n// ## Hello, Loft!\n// Here is a small first program to make things concrete.\n// 'println' prints a line of text to standard output.\n// Format strings let you embed values directly: write the variable inside '{}'.\nfn main() {\n  // Variables are declared by assigning a value — no 'let', 'var', or type annotation.\n  // The type is inferred: greeting is text, x and y are integers.\n  greeting = \"Hello, Loft!\";\n  x = 6;\n  y = 7;\n  assert(x * y == 42, \"Arithmetic works as you would expect\");\n  // Format strings use '{expression}' — you can embed any expression, not just names.\n  assert(\"{greeting} The answer is {x * y}.\" == \"Hello, Loft! The answer is 42.\", \"Format strings interpolate expressions\");\n  // ## Null in practice\n  // Dividing by zero produces null when defended with `?? null` or a\n  // following null-check, instead of crashing.  In a condition, null\n  // is treated as false, so '!' turns it into true.  This makes it\n  // easy to handle unexpected values gracefully.  Without a defense,\n  // bare `1 / 0` halts in development with a typed error; in\n  // production it logs a warning + continues with the null sentinel.\n  zero = 0;\n  result = 12 / zero ?? null;\n  assert(!result, \"Dividing by zero gives null when defended\");\n  // ## if is an expression\n  // Every 'if/else' can be used on the right side of an assignment.\n  // The value of the chosen branch becomes the value of the whole expression.\n  label = if x * y == 42 {\n    \"correct\"\n  } else {\n    \"wrong\"\n  };\n  assert(label == \"correct\", \"if-expression picked the right branch\");\n  // ## A quick taste of collections\n  // A vector is an ordered list of values.\n  // Fill it with a list literal using square brackets.\n  // Access elements by 0-based index.\n  // 'len()' tells you how many elements there are.\n  scores =[10, 20, 30, 40];\n  assert(scores[2] == 30, \"0-based indexing: element 2 is 30\");\n  assert(len(scores) == 4, \"len counts elements\");\n  total = 0;\n  for s in scores {\n    total += s;\n  }\n  assert(total == 100, \"Summed all scores: {total}\");\n}",
"keywords": "// This page covers the building blocks that shape how your program makes\n// decisions and repeats work: conditions, loops, breaks, and a few loop\n// helpers that make common patterns shorter. Every example is verified: most\n// with an assert naming the exact expected result, and the first with a panic\n// that would fire if the rule it shows did not hold.\nfn main() {\n  // ## Conditionals\n  // 'if' runs a block only when its condition is true. If the condition is\n  // false the block is skipped entirely — nothing else happens.\n  // 'panic' stops the program immediately with a message. During development\n  // it is a clear way to mark situations that should never occur.\n  if 2 > 5 {\n    panic(\"Incorrect test\");\n  }\n  // Combine conditions with 'and' / 'or' (or their symbol equivalents '&&' / '||').\n  // Note that '&' is the bitwise AND operator — it works on the individual\n  // 1s and 0s inside a number, which is different from the logical 'and' keyword\n  // that works on true/false values.\n  // An 'if/else' chain picks exactly one branch to execute.\n  a = 12;\n  if a > 10 and a & 7 == 4 {\n    a += 1;\n  } else {\n    a -= 1;\n  }\n  // Text enclosed in double quotes can contain expressions inside curly braces —\n  // the expression is evaluated and its result is inserted into the text.\n  // 'assert' checks that its first argument is true; if it is false the\n  // second argument is printed as an error message.\n  assert(a == 13, \"Incorrect value {a} != 13\");\n  // ## if as an expression\n  // An 'if', a 'match', and a bare '{ }' block all produce a value — the last\n  // expression inside them. That means you can use 'if/else' on the right-hand\n  // side of an assignment, picking between two values based on a condition. No\n  // ternary operator needed. Loops are the exception: 'for' and 'while' are\n  // statements, so 'x = for i in 1..3 { i }' does not compile.\n  b = if a == 13 {\n    \"Correct\"\n  } else {\n    \"Wrong\"\n  };\n  assert(b == \"Correct\", \"Logic expression\");\n  // ## Iteration\n  // 'for x in a..b' loops over the integers starting at a and stopping\n  // before b (exclusive upper bound). Use '..=' to include the upper bound.\n  // Here we sum 1 + 2 + 3 + 4 + 5 = 15.\n  t = 0;\n  for i in 1..6 {\n    t += i;\n  }\n  assert(t == 15, \"Total was {t} instead of 15\");\n  // 'rev(range)' reverses the direction of any range.\n  // '1..=5' is inclusive, so it visits 5, 4, 3, 2, 1 in that order.\n  // Multiplying each digit into a running total builds the number 54321.\n  t = 0;\n  for i in rev(1..=5) {\n    t = t * 10 + i;\n  }\n  assert(t == 54321, \"Result was {t} instead of 54321\");\n  // ## The other loop: while\n  // Loft has two loop statements: 'for', which walks a range or a collection, and\n  // 'while', which repeats as long as its condition holds. A 'for' over a range\n  // carries its own upper bound, so it is the one to reach for; a 'while' does not,\n  // and 'while true { }' runs until something stops it. Because nothing bounds a\n  // 'while', its body must move the condition towards false — here 'n += 1' is what\n  // ends the loop. This is the same sum as the 'for' above, written the other way.\n  n = 1;\n  t = 0;\n  while n <= 5 {\n    t += n;\n    n += 1;\n  }\n  assert(t == 15, \"while summed to {t} instead of 15\");\n  // ## Nested loops and break\n  // 'break' exits the nearest enclosing loop immediately.\n  // To exit an outer loop from inside an inner one, write 'outerVar#break'.\n  // Here x#break leaves both loops when the product x*y reaches 16.\n  b = \"\";\n  for x in 1..5 {\n    for y in 1..5 {\n      if y > x {\n        break;\n        // this breaks the inner y loop\n      }\n      if x * y >= 16 {\n        x#break;\n      }\n      if len(b) > 0 {\n        b += \"; \";\n      }\n      b += \"{x}:{y}\";\n    }\n  }\n  assert(b == \"1:1; 2:1; 2:2; 3:1; 3:2; 3:3; 4:1; 4:2; 4:3\", \"Incorrect sequence '{b}'\");\n  // ## Skipping an iteration: continue\n  // 'continue' is the sibling of 'break': instead of leaving the loop it skips\n  // the rest of the current iteration and moves on to the next value. Here we\n  // sum 1..=5 but skip 3, so the total is 1 + 2 + 4 + 5 = 12.\n  t = 0;\n  for i in 1..=5 {\n    if i == 3 {\n      continue;\n    }\n    t += i;\n  }\n  assert(t == 12, \"continue skipped 3: total was {t} instead of 12\");\n  // ## Loop helpers: #first and #count\n  // Inside a loop body you have access to some useful metadata about the\n  // current iteration. 'x#first' is true only for the very first element\n  // that passes the filter. 'x#count' is a zero-based index counting only\n  // the elements that were not filtered out.\n  // An 'if' clause directly after 'in range' filters which values enter the loop —\n  // here we skip every value where x % 3 == 1, keeping 2, 3, 5, 6, 8, 9.\n  b = \"\";\n  for x in 1..=9 if x % 3 != 1 {\n    if !x#first {\n      b += \", \";\n    }\n    b += \"{x#count}:{x}\";\n  }\n  assert(b == \"0:2, 1:3, 2:5, 3:6, 4:8, 5:9\", \"Sequence '{b}'\");\n  // ## Formatting a loop inline\n  // A for loop can appear inside a format string. The results are collected\n  // into a bracketed, comma-separated list. A format specifier after the\n  // closing brace is applied to every element — ':02' means at least 2 digits,\n  // zero-padded. This is handy for building compact representations on the fly.\n  assert(\"a{for x in 1..7 {x*2}:02}b\" == \"a[02,04,06,08,10,12]b\", \"Format range\");\n}",
"texts": "// Text is one of the most frequently used types in any real program — for\n// output, for reading input, for building messages. This page shows you how\n// Loft stores and manipulates text, how to measure it, slice it, search it,\n// and format it exactly the way you need.\n//\n// The key thing to know upfront: Loft stores text as a sequence of bytes using\n// UTF-8 encoding — the same format used on the web. Plain ASCII letters, digits,\n// and punctuation each take exactly one byte. Accented letters, emoji, and many\n// non-Latin scripts take 2–4 bytes. So there are two different counts, and which\n// one you get depends on the operation: anything that takes a POSITION — indexing,\n// slicing, 'find' — counts bytes, while 'len()' and iterating a text count\n// characters. Positions in bytes are fast and simple; the thing to watch is mixing\n// the two counts, which has its own section below.\nfn main() {\n  // ## Joining and measuring text\n  // Use '+' to join two pieces of text into one. The result is a new value —\n  // neither of the originals is modified.\n  // Placing a value name inside curly braces inside a format string inserts\n  // the value as text. You can also control the width: '{a:4}' pads the\n  // value on the right to at least 4 characters.\n  a = \"1\" + \"2\";\n  assert(\"'{a:4}'\" == \"'12  '\", \"Formatting text\");\n  assert(len(a + \"123\") == 5, \"Text length\");\n  // 'len()' counts characters (Unicode code points), the human count: an emoji\n  // like '😃' is one character, a heart symbol '♥' is one, and each ASCII letter\n  // is one. For the UTF-8 byte length (bounds checks, byte indexing) use 'size()'.\n  assert(len(\"😃\") == 1, \"Emoji is one character\");\n  assert(len(\"♥\") == 1, \"Heart is one character\");\n  assert(len(\"abc\") == 3, \"ASCII character count\");\n  // ## Do not mix the two counts\n  // 'len()' is a character count and 's[i]' is a byte index, so walking one with\n  // the other goes wrong on any text that is not pure ASCII: the loop runs too few\n  // times AND re-reads the bytes inside a multi-byte character. Over \"Hi 😊!\",\n  // 'for i in 0..len(s) { s[i] }' yields \"Hi 😊😊\" — the '!' is silently gone and\n  // the emoji appears twice. Nothing fails; the answer is just wrong.\n  // Iterate the characters with 'for c in text', or, when you really do mean bytes,\n  // walk '0..size(text)'. The compiler reports the mix for you as\n  // warning[text-index-char-bound].\n  mixed = \"Hi 😊!\";\n  assert(len(mixed) == 5, \"five characters, not eight\");\n  assert(size(mixed) == 8, \"eight bytes, not five\");\n  // ## Reading individual characters\n  // Square brackets with a single byte index give you the character at that\n  // position. For plain ASCII text every byte is one character, so indexing\n  // by position is straightforward. Loft will return the full character\n  // even if it spans multiple bytes.\n  s = \"ABCDE\";\n  assert(s[0] == 'A', \"Character at byte 0\");\n  assert(s[2] == 'C', \"Character at byte 2\");\n  // ## Slicing text\n  // A slice 's[start..end]' gives you the bytes from 'start' up to but not\n  // including 'end'. You can omit the start to begin at 0, or omit the end\n  // to go all the way to the last byte. Loft snaps offsets to valid character\n  // boundaries so you can never accidentally cut a multi-byte character in half.\n  assert(s[0..2] == \"AB\", \"Explicit start slice\");\n  assert(s[..2] == \"AB\", \"Open-start slice\");\n  assert(s[1..4] == \"BCD\", \"Sub-string by byte range\");\n  assert(s[3..] == \"DE\", \"Open-ended sub-string\");\n  // A negative end index counts backwards from the end of the text.\n  // '-1' means \"stop one byte before the very last byte\". Combined with a\n  // start offset this lets you trim a known suffix without knowing the exact length.\n  txt = \"12😊🙃45\";\n  assert(txt[2.. - 1] == \"😊🙃4\", \"UTF-8 sub-string by byte range\");\n  // That counts BYTES, and the offset still snaps to a character boundary — so it\n  // trims a one-byte suffix like '5' above, and leaves a multi-byte one whole. Here\n  // both -1 and -2 land inside the trailing emoji and snap back around it, returning\n  // the text unchanged. Trim by bytes only when you know the suffix is ASCII.\n  assert(\"ab😊\"[.. - 1] == \"ab😊\", \"a multi-byte suffix is not trimmed by -1\");\n  assert(\"ab😊\"[.. - 2] == \"ab😊\", \"nor by -2\");\n  // ## Iterating over characters\n  // A 'for' loop over a text value visits one character at a time,\n  // even when characters span multiple bytes. Two loop helpers give you\n  // position information without any extra code:\n  // 'c#index' is the byte offset where the current character starts.\n  // 'c#next' is the byte offset immediately after the current character ends.\n  // This makes it easy to build a byte-offset map or to collect characters\n  // starting from a specific position.\n  result = \"\";\n  positions = [];\n  nexts = [];\n  for c in \"Hi 😊!\" {\n    positions += [c#index];\n    nexts += [c#next];\n    if c#index >= 3 { result += c; }\n  }\n  assert(result == \"😊!\", \"Character iteration was {result}\");\n  assert(\"{positions}\" == \"[0,1,2,3,7]\", \"Character positions was {positions}\");\n  assert(\"{nexts}\" == \"[1,2,3,7,8]\", \"Character nexts was {nexts}\");\n  // ## Searching inside text\n  // These built-in functions answer common \"does this text contain…?\" questions.\n  // 'starts_with' and 'ends_with' check the boundaries.\n  // 'find' returns the byte offset of the first match, or null if not found.\n  // 'contains' is true if the needle appears anywhere in the text.\n  // All positions are byte offsets, consistent with 'len()' and slicing.\n  assert(\"something\".starts_with(\"some\"), \"starts_with\");\n  assert(\"something\".ends_with(\"thing\"), \"ends_with\");\n  assert(\"something\".find(\"th\") == 4, \"find returns byte offset\");\n  assert(\"a longer text\".contains(\"longer\"), \"contains\");\n  // 'trim()' removes spaces and other whitespace from both ends of a text value.\n  // It is useful when reading user input or parsing text from a file.\n  assert(trim(\"  hello  \") == \"hello\", \"trim\");\n  // ## Escaping braces in format strings\n  // Inside a format string '{' and '}' are special: they introduce an\n  // interpolated expression. To include a literal brace in the output,\n  // double it: '{{' produces '{' and '}}' produces '}'.\n  brace_inner = \"cd\";\n  assert(\"ab{{cd}}e\" == \"ab{{{brace_inner}}}e\", \"Escaping braces\");\n  // ## Aligning text in a fixed-width field\n  // The ':' specifier controls alignment and width. '<' left-aligns the value and\n  // '>' right-aligns it. The default depends on the TYPE: text is left-aligned (as\n  // '{a:4}' and '{vr:6}' here both show), while numbers are right-aligned, which is\n  // what lines a column of figures up. The width can be a constant or a small\n  // arithmetic expression — here '2+3' evaluates to 5, giving a field of width 5.\n  vr = \"abc\";\n  assert(\"1{vr:<2+3}2{vr}3{vr:6}4{vr:>7}\" == \"1abc  2abc3abc   4    abc\", \"Text alignment\");\n}",
"integers": "// Numbers are at the heart of almost every program. This page covers the\n// integer types Loft provides, the arithmetic and bitwise operations you can\n// perform on them, how to convert between numbers and text, and what Loft\n// does when something goes wrong — such as dividing by zero.\n//\n// The default number type is 'integer': a 64-bit signed whole number, the\n// same as i64 in Rust. It can hold values from about −9 quintillion to\n// +9 quintillion (roughly ±9.2 × 10^18), so everyday counts and very large\n// numbers both fit in the one type — there is no separate 'long'.\n// For decimal (fractional) numbers, see the Float page.\nfn main() {\n  // ## Converting between numbers and text\n  // Wrapping a value in '{...}' inside a string formats it as text.\n  // Going the other way, 'as integer?' parses a text value into a number. Write\n  // the '?': a text parse can fail, so a bare 'as integer' is refused at compile\n  // time (\"a text parse `as integer` may fail, and a bare cast asserts it cannot\").\n  // The '?' is you accepting the failure case, and the result is null — not a\n  // crash — when the text does not parse.\n  v = 4;\n  assert(\"{v}\" == \"4\", \"Format integer as text\");\n  assert(\"123\" as integer? == 123, \"Parse text to integer\");\n  assert(!(\"abc\" as integer?), \"Unparseable text gives null\");\n  // ## Arithmetic and operator precedence\n  // Loft follows standard mathematical precedence: '*' and '/' before '+' and '-'.\n  // Bitwise operators (<<, &, ^) have their own precedence — when mixing them with\n  // arithmetic, parentheses make your intent clear and avoid surprises.\n  // Note: '^' is XOR, not exponentiation. For powers use 'pow(base, exp)' — a FLOAT\n  // function, so 'pow(2, 3)' does not resolve: raise in floats and come back. It\n  // answers a NULLABLE float ('float?'), because a power can be uncomputable, so the\n  // trip back is a checked cast or a discharge:\n  //   pow(base, exp) as integer?           // the number, or null\n  //   (pow(base, exp) ?? 0.0) as integer   // your own default instead\n  // A bare 'as integer' is refused (\"cannot cast a possibly-null `float?` to the\n  // non-null `integer`\"). It does compile when BOTH arguments are literals, and that\n  // is the one shape which does not generalise — write the '?' and it works wherever\n  // the base is a variable, which is everywhere real.\n  assert(1 + 2 * 4 == 9, \"Multiplication before addition\");\n  assert(1 + 2 << 2 == 12, \"Shift: (1+2) << 2 = 12\");\n  assert(0x0a8 & 15 == 8, \"Bitwise AND masks low 4 bits\");\n  assert(42 ^ 0b111111 == 21, \"Bitwise XOR\");\n  assert(105 % 100 == 5, \"Modulus (remainder)\");\n  // Raised from a VARIABLE base on purpose: the literal-only spelling is exactly the\n  // one that stops compiling the moment a reader puts their own number in it.\n  pw_base = 2.0;\n  assert(pow(pw_base, 3.0) as integer? == 8, \"pow() for exponentiation\");\n  assert((pow(pw_base, 10.0) ?? 0.0) as integer == 1024, \"…or discharge, then cast\");\n  // 'abs()' returns the absolute value — the distance from zero, always positive.\n  assert(1 + abs(-2) == 3, \"abs(-2) == 2\");\n  // ## Division by zero — produces null and keeps running\n  // Most languages crash on division by zero.  Loft does NOT: a divide (or\n  // modulo) by zero is uncomputable, so it produces null and execution\n  // CONTINUES — the spreadsheet model, where one bad cell shows an error but\n  // the rest still recalculate.  This holds the same everywhere (development,\n  // test, and production) — one bad calculation never halts the run.\n  // Where the divisor is a literal zero in your source, loft can see it before the\n  // program runs and warns (next section). Where it is only zero at RUN time there is\n  // no warning — you get null, and when loft knows the reason it prints it, so a bare\n  // '{12 / a}' shows 'null(/0)' rather than a bare 'null'. Recover with '??', or test\n  // the result for null: nothing else tells you, so a divide whose divisor could be\n  // zero is one you handle rather than one you are reminded about.\n  a = 2 * 2;\n  a -= 4;\n  // a is now 0\n  assert(!(12 / a ?? null), \"Division by zero gives null when defended with `?? null`\");\n  // ## Warning when you write a literal zero divisor\n  // When the divisor is a literal 0 written directly in your source code, loft\n  // warns you while reading your code (before running it), because that is almost\n  // certainly a mistake:\n  //   n / 0   // warning: Division by constant zero\n  //   n % 0   // warning: Modulo by constant zero\n  // Use a variable (like 'a' above) when you intentionally want\n  // null-on-zero division without a warning.\n  // ## Embedding integers in text\n  assert(\"a{12}b\" == \"a12b\", \"Integer in format string\");\n  // A full expression can appear inside '{...}', not just a variable name.\n  assert(\"a{1 + 2 * 3}b\" == \"a7b\", \"Expression in format string\");\n  // ## Number format specifiers\n  // After a ':' inside '{...}' you can control how a number is displayed:\n  //   #x  — hexadecimal with '0x' prefix\n  //   o   — octal\n  //   b   — binary\n  //   +   — always show a sign (+ or -)\n  //   N   — minimum field width (space-padded on the left)\n  //   0N  — minimum field width (zero-padded on the left)\n  assert(\"a{1+2+32:#x}b\" == \"a0x23b\", \"Hex format with 0x prefix\");\n  assert(\"{12:o}\" == \"14\", \"Octal\");\n  assert(\"{12:+4}\" == \" +12\", \"Sign and width\");\n  assert(\"{1:03}\" == \"001\", \"Zero-padded width\");\n  assert(\"{42:b}\" == \"101010\", \"Binary\");\n  // Hexadecimal literals in source code accept both lower and upper case digits.\n  assert(0xff == 255, \"Lowercase hex literal\");\n  assert(0xFF == 255, \"Uppercase hex literal\");\n  assert(0x2A == 42, \"Uppercase hex digit\");\n  // ## Large integers\n  // Because 'integer' is 64-bit, values far past the old 2-billion limit work\n  // directly — no separate type is needed. Arithmetic, comparisons, and the\n  // format specifiers above all behave the same at these magnitudes.\n  big = 1000000000 * 5;\n  assert(big == 5000000000, \"Integers well past 2 billion\");\n  assert(\"{big}\" == \"5000000000\", \"Large integer formatted as text\");\n  // ## Common pitfall: integer overflow\n  // A calculation whose result is too large to represent overflows — and in\n  // loft an overflow is uncomputable, so the result is null. It never wraps to\n  // a silently-wrong number, and it never crashes; execution continues with the\n  // null, exactly like divide-by-zero above. Check the result for null (or keep\n  // intermediate values in range) when multiplying or summing very large numbers.\n  //\n  // A sized integer ('u8', 'i16', a field declared 'integer limit(0, 255)') has\n  // a smaller range, so it overflows sooner — and where it lands depends on one\n  // thing: whether the slot can hold null. A nullable one ('u8?') gets the null,\n  // the same as above. A non-nullable one has nowhere to put it, so it gets the\n  // type's default instead — 0 for every range that includes zero. What you\n  // never get is a wrapped number.\n  small: u8? = 250;\n  small += 10;\n  assert(small == null, \"A nullable sized integer overflows to null\");\n  assert((small ?? 0) == 0, \"…and '??' recovers from it, like any other null\");\n  fixed: u8 = 250;\n  fixed += 10;\n  assert(fixed == 0, \"A non-nullable one takes its type's default instead\");\n}",
"boolean": "// A boolean value is either 'true' or 'false'. Booleans appear naturally\n// wherever you make a decision: in 'if' conditions, loop filters, and\n// comparisons. Loft adds a third state called 'null' — meaning \"no value\" —\n// which behaves like false whenever a boolean is expected.\n//\n// This design means you rarely need to write a separate null-check: '!x' is\n// true both when x is false and when x is null.\nfn main() {\n  // A comparison produces a boolean result directly.\n  // '!' flips a boolean: true → false, false → true.\n  assert(!(3 > 2 + 4), \"3 is not greater than 6\");\n  assert(true as text == \"true\", \"Convert boolean to text\");\n  // ## Logical operators: and / or\n  // 'and' (also '&&') is true only when both sides are true.\n  // 'or'  (also '||') is true when at least one side is true.\n  // Both skip the right side when the left side already determines the result.\n  // For example, 'false and X' is always false, so X is never evaluated.\n  // This matters when the right side could produce null or has a side effect.\n  assert(1 > 0 and 2 > 1, \"Both conditions true\");\n  assert(1 > 2 or 3 > 2, \"Second condition true\");\n  assert(!(1 > 2 && 3 > 2), \"First false → whole 'and' is false\");\n  assert(!(1 > 2 || 3 > 4), \"Both false → 'or' is false\");\n  // ## Null in boolean context\n  // Division by zero (and other failed operations) produce null when\n  // defended with `?? null` (or `if result != null { ... }` after the\n  // assignment).  Null in a boolean context is treated as false, so\n  // '!' is true.  This lets you write guard clauses without a separate\n  // null-check syntax:\n  //   if !result { ... handle missing value ... }\n  // Even without `?? null`, a bare divide never halts: it yields null and execution\n  // continues, the same everywhere — development, test, and production.\n  //\n  // The `?? null` is not what makes that safe, and it silences nothing. loft warns\n  // about a divisor that is a literal 0 in your source, while READING your code, and\n  // it warns whether or not you wrote `?? null`; a divisor that is only zero at RUN\n  // time is not warned about at all. What `?? null` changes is the VALUE: loft prints\n  // the reason it knows, so an undefended result formats as 'null(/0)', and coalescing\n  // it to a plain null throws that reason away. Reach for `?? null` when you want the\n  // bare null, and for `?? <value>` when you want a number — not to quiet a warning.\n  zero = 0;\n  assert(!(12 / zero ?? null), \"null from division-by-zero is false-like when defended\");\n  assert(\"{12 / zero}\" == \"null(/0)\", \"an undefended result carries its reason\");\n  assert(\"{12 / zero ?? null}\" == \"null\", \"…and `?? null` trades the reason for a plain null\");\n  assert(12 > 0, \"positive integer is true\");\n  // ## Bitwise operators\n  // While 'and'/'or' work on true/false values, bitwise operators work on\n  // the individual bits of an integer. They are useful for flags, masks,\n  // and low-level data manipulation.\n  //\n  //   '&'  — keeps only bits set in BOTH operands (AND)\n  //   '|'  — keeps bits set in EITHER operand (OR)\n  //   '<<' — shift bits left N positions  (×2^N)\n  //   '>>' — shift bits right N positions (÷2^N)\n  //\n  // Tip: '&' binds less tightly than comparison operators. Use parentheses\n  // when you mix bitwise and comparison expressions in the same condition.\n  assert((0x0f & 0xa8) == 8, \"Bitwise AND: keeps only bits in both\");\n  assert((0xf0 | 0x0f) == 0xff, \"Bitwise OR: combines bits from either\");\n  assert(1 << 4 == 16, \"Left shift: 1 × 2^4 = 16\");\n  assert(256 >> 3 == 32, \"Right shift: 256 ÷ 2^3 = 32\");\n  // ## Negation\n  // '!' is the logical NOT operator. It flips any boolean expression.\n  assert(!false, \"not false is true\");\n  assert(!(1 > 2), \"not false comparison is true\");\n  // ## Formatting booleans\n  // Booleans can be embedded in a format string like any other value.\n  // The '^' alignment specifier centres the value in a field of given width.\n  // '<' aligns left, '>' aligns right (right-alignment is the default).\n  assert(\"1{true:^7}2\" == \"1 true  2\", \"Centred boolean in field of width 7\");\n  assert(\"{false}\" == \"false\", \"Plain boolean format\");\n  // ## '&' vs 'and'\n  // '&' is bitwise AND on integers; 'and' (or '&&') is logical AND on booleans.\n  // Writing 'a & b' where both sides are booleans is a compile error — the\n  // compiler requires 'and' or '&&' for boolean logic.\n  flag_a = 3 > 1;\n  // true\n  flag_b = 4 > 2;\n  // true\n  assert(flag_a and flag_b, \"Correct: logical AND on two booleans\");\n}",
"float": "// A 'float' stores a number with a decimal point, like 3.14 or -0.001.\n// It gives you about 15 significant digits of precision — enough for scientific\n// work, games, and most real-world maths.\n// When you write a number with a decimal point in Loft, it is automatically a float.\nfn main() {\n  // Write a decimal point in a literal and Loft treats the whole expression as a float.\n  // The usual arithmetic operators (+, -, *, /) all work the way you would expect.\n  assert(1.5 + 0.5 == 2.0, \"Float addition\");\n  assert(3.0 / 2.0 == 1.5, \"Float division\");\n  assert(2.0 * 1.5 == 3.0, \"Float multiplication\");\n  // ## Undefined results are null ('float?') — but infinities are NOT undefined\n  // Some float operations have no real answer for some inputs: 'sqrt' of a negative,\n  // 'ln'/'log' of a NEGATIVE, 'asin'/'acos' outside -1..1, an out-of-domain 'pow',\n  // '%' by zero, and 0.0/0.0. Rather than crash, Loft yields null for these — so\n  // '/', '%', 'sqrt', 'ln', 'log', 'pow', 'asin' and 'acos' each produce a NULLABLE\n  // float ('float?'). The null then propagates: any further arithmetic on a null\n  // stays null, and '?? fallback' discharges it when you need a plain float.\n  //\n  // Read the boundary carefully, because it is not \"anything unusual is null\".\n  // Floats keep IEEE INFINITY, and infinity is a value, not a missing one:\n  //\n  //   1.0 / 0.0   is  inf        0.0 / 0.0   is  null\n  //  -1.0 / 0.0   is -inf        1.0 % 0.0   is  null\n  //   ln(0.0)     is -inf        ln(-1.0)    is  null\n  //\n  // So a '?? fallback' does NOT rescue a division by zero the way it rescues a\n  // sqrt of a negative — the infinity is not null, sails through the guard, and\n  // propagates through every later sum. When a zero divisor is possible, test the\n  // DIVISOR rather than defending the result.\n  assert((sqrt(-1.0) ?? 0.0) == 0.0, \"sqrt of a negative is null\");\n  assert(((sqrt(-1.0) + 5.0) ?? 0.0) == 0.0, \"null propagates through arithmetic\");\n  fz = 0.0;\n  fp = 1.0;\n  assert(\"{fp / fz}\" == \"inf\", \"a non-zero over zero is an infinity, not a null\");\n  assert(((fp / fz) ?? -1.0) > 1000000.0, \"…so `??` does not rescue it\");\n  assert(((fz / fz) ?? -1.0) == -1.0, \"…while 0.0/0.0 really is null, and `??` does\");\n  // The 'f' suffix selects single-precision floats, which take half the memory\n  // of a regular float but have fewer decimal digits of accuracy. This trade-off\n  // is common in graphics and audio code where exact decimal values matter less\n  // than speed or memory.\n  x = 0.1f + 2 * 1.0f;\n  assert(x == 2.1f, \"Single precision float\");\n  // 'as float' converts an integer to a float so you can mix them in calculations.\n  // Putting a float inside '{...}' converts it to text for display.\n  // You can also go the other way: '\"1.5\" as float?' parses the text back to a number.\n  // The '?' is required — a bare 'as float' on text is refused for the same reason a\n  // bare 'as integer' is (\"a text parse `as float` may fail, and a bare cast asserts\n  // it cannot\"), because the text might not be a number.\n  assert(3 as float == 3.0, \"Integer to float\");\n  assert(\"1.5\" as float? == 1.5, \"Text to float\");\n  assert(\"{1.5}\" == \"1.5\", \"Float formatted as text\");\n  // ## Formatting Floats\n  // Put a colon after the value inside '{...}' to control how it looks.\n  // '{value:width.precision}' — 'width' is the minimum number of characters printed\n  // (padded with spaces on the left); 'precision' fixes the number of decimal places.\n  // You can use either part on its own: '{value:.2}' just fixes decimal places,\n  // '{value:5}' just sets the minimum width.\n  assert(\"{1.2:4.2}\" == \"1.20\", \"Float with width and precision\");\n  assert(\"{334.1:.2}\" == \"334.10\", \"Float with precision only\");\n  assert(\"{1.4:5}\" == \"  1.4\", \"Float with width only\");\n  // ## Math Functions\n  // 'PI' is a built-in constant (approximately 3.14159265358979).\n  // Multiplying it by 1000 and rounding gives 3142, which confirms the value is correct.\n  assert(round(PI * 1000.0) == 3142.0, \"PI constant\");\n  // 'pow(base, exponent)' raises a number to a power — this is exponentiation.\n  // Note: '^' in Loft is bitwise XOR, NOT exponentiation. Always use pow() for powers.\n  // 'log(value, base)' is the inverse: log(x, b) answers \"b to the what power equals x?\"\n  // Here: 4^5 = 1024, and log(1024, 2) = 10 because 2^10 = 1024.\n  assert(log(pow(4.0, 5), 2) == 10.0, \"log base 2 of 4^5\");\n  // 'sin' and 'cos' work in radians, not degrees.\n  // A full circle is 2*PI radians; a half circle (180 degrees) is PI radians.\n  // sin(PI) should be exactly zero but computers use approximations for decimal\n  // numbers, so you may get something like 0.0000000001 instead. We use ceil()\n  // to round it up to 0. cos(PI) is exactly -1, so the whole expression\n  // ceil(~0 + -1 * 1000) lands at -1000.\n  assert(ceil(sin(PI) + cos(PI) * 1000) == -1000.0, \"sin and cos\");\n  // 'abs()' returns the absolute value — the distance from zero, always non-negative.\n  // Useful any time you care about magnitude but not direction.\n  assert(abs(-2.5) == 2.5, \"Absolute value of float\");\n  // 'round()' picks the nearest whole number (0.5 rounds up).\n  // 'ceil()' always rounds up to the next whole number, even for 2.01.\n  // 'floor()' always rounds down to the previous whole number, even for 2.99.\n  // All three give back a float, not an integer — so 3.0, not 3.\n  assert(round(2.6) == 3.0, \"round up\");\n  assert(round(2.4) == 2.0, \"round down\");\n  assert(ceil(2.1) == 3.0, \"ceil\");\n  assert(floor(2.9) == 2.0, \"floor\");\n  // Single-precision floats work inside format strings just like regular floats.\n  assert(\"a{0.1f + 2 * 1.0f}b\" == \"a2.1b\", \"Single-precision format\");\n}",
"functions": "// Functions let you give a reusable piece of logic a name so you can call it\n// from multiple places without copying code.\n// This page covers: declaring functions, default argument values, reference parameters\n// (so a function can modify the caller's variable), early return, const parameters,\n// and type-based dispatch.\n// ## Declaring Functions\n// The keyword 'fn' starts a function definition.\n// List parameters as 'name: type' separated by commas.\n// '-> type' declares what the function gives back.\n// The last expression in the body is returned automatically — no 'return' needed there.\n// Default values let callers skip optional arguments.\nfn greet(name: text, greeting: text = \"Hello\") -> text {\n  greeting + \", \" + name + \"!\"\n}\n// ## Default arguments that involve other arguments\n// A default value can be any expression, not just a literal — including one that\n// references earlier parameters, which are in scope by the time their default is\n// evaluated. So 'end' can default directly to the length of the earlier 't'.\nfn substring(t: text, start: integer = 0, end: integer = len(t)) -> text {\n  t[start..end]\n}\n// ## Named Arguments\n// When a function has several parameters with defaults, you can skip middle ones\n// by naming the arguments you want to provide. Positional arguments come first;\n// once you use a name, all remaining arguments must also be named.\nfn connect(host: text, port: integer = 8080, tls: boolean = true) -> text {\n  \"{host}:{port}:{tls}\"\n}\n// ## Reference Parameters and Defaults\n// A function with no '-> type' is called for its side effects, not its result.\n// Adding '&' before a parameter type makes it a reference: the function receives a\n// direct link to the caller's variable and can read or write it.\n// Without '&', Loft copies the value in, so changes inside the function stay local.\n// Default values (written '= value' after the type) are substituted when the caller\n// omits that argument.\n\nfn add(a:  & integer, b: integer, c: integer = 0) {\n  a += b + c;\n}\n// ## Early Return\n// Use 'return value;' to exit a function before reaching the end.\n// This is handy for guard clauses: handle the special cases first, then write the\n// normal path without extra nesting.\n\nfn classify(n: integer) -> text {\n  if n < 0 {\n    return \"negative\";\n  }\n  if n == 0 {\n    return \"zero\";\n  }\n  \"positive\"\n}\n// ## Const and Reference Parameters\n// Write 'const' with the TYPE, not before the name — 'fn f(s: const text)', not\n// 'fn f(const s: text)', which does not parse. It tells the compiler \"this function\n// must never change this value\", and the compiler enforces it: assigning to a const\n// parameter is a compile error (\"Cannot modify const parameter\").\n// '&' is the opposite promise: \"this function will modify this value.\"\n// Declaring '&' without actually writing to the parameter is also a compile error\n// (\"Parameter 'a' has & but is never modified; remove the &\").\n// These rules make it easy to read a function signature and know what it does to its inputs.\n//\n// 'const' earns its keep on a parameter the function COULD write through — a text, a\n// vector, a struct. On a primitive you never modify it is reported as needless\n// ('needless-const-parameter'), because a plain 'integer' parameter is already a copy\n// and const adds nothing to it.\n\nfn shout(s: const text) -> text {\n  s + \"!\"\n}\n\nfn scale(a: integer, factor: integer) -> integer {\n  a * factor\n}\n// ## Type-Based Dispatch\n// You can define two functions with the same name as long as their parameter types differ.\n// Loft picks the right one at compile time based on the type of the argument you pass.\n\nfn describe_int(v: integer) -> text {\n  \"integer:{v}\"\n}\n\nfn describe_text(v: text) -> text {\n  \"text:{v}\"\n}\n// ## Function References\n// Writing a function's NAME on its own creates a reference to it that you can store or\n// pass around — 'f = double_it', with no 'fn' in front. ('fn double_it' is refused:\n// \"Use the function name directly, without 'fn' prefix\".)\n// The compiler checks that the name exists — a typo is a compile error.\n// The result has type 'fn(param_types) -> return_type' and can be:\n//   - stored in a variable,\n//   - called directly with 'f(args)', and\n//   - passed as a parameter to another function.\n\nfn double_it(x: integer) -> integer {\n  x * 2\n}\n\nfn negate_it(x: integer) -> integer {\n  - x\n}\n\nfn apply_fn(f:  fn(integer) -> integer, x: integer) -> integer {\n  f(x)\n}\n\n// ## Lambda Expressions\n// A lambda is an anonymous (unnamed) function written right where you need it.\n// Use the full form when you want to be explicit about types:\n//   fn(param: type) -> return_type { body }\n// Use the short form (pipe-bar syntax) when the call site already knows the types:\n//   |param| { body }\n// Both forms work anywhere a function reference is expected — especially with\n// map, filter, and reduce.  The short form does not allow type annotations;\n// use the full fn(…) form when you need explicit types.\n// Lambdas that need outer variables can capture them: see the Closures page.\n\n\nfn main() {\n  // Passing both arguments explicitly overrides the default.\n  assert(greet(\"World\", \"Hi\") == \"Hi, World!\", \"Explicit argument\");\n  // Leaving out the second argument causes Loft to use the default \"Hello\".\n  assert(greet(\"World\") == \"Hello, World!\", \"Default argument\");\n  // 'add' takes 'a' by reference, so every call updates the original variable 'v'.\n  // Watch how v accumulates: 1 -> 3 -> 8.\n  v = 1;\n  add(v, 2);\n  // v = 1 + 2 = 3\n  add(v, 4, 1);\n  // v = 3 + 4 + 1 = 8\n  assert(v == 8, \"Reference parameter: {v}\");\n  // 'classify' uses early returns to handle each case separately.\n  assert(classify(-5) == \"negative\", \"Classify negative\");\n  assert(classify(0) == \"zero\", \"Classify zero\");\n  assert(classify(3) == \"positive\", \"Classify positive\");\n  // 'scale' uses plain parameters (no 'const', no '&'): it only reads them to\n  // compute the product, so the caller's values are never touched.\n  assert(scale(3, 7) == 21, \"scale(3,7)\");\n  // 'shout' promises not to change its text, and the compiler holds it to that.\n  assert(shout(\"hi\") == \"hi!\", \"const parameter: {shout(\\\"hi\\\")}\");\n  // Loft selects the right function based on the type of the argument.\n  assert(describe_int(42) == \"integer:42\", \"Integer describe\");\n  assert(describe_text(\"hi\") == \"text:hi\", \"Text describe\");\n  // A function reference is stored in a variable with type 'fn(...) -> ...'.\n  // Calling it looks exactly like a regular function call.\n  f = double_it;\n  assert(f(5) == 10, \"fn-ref stored and called: {f(5)}\");\n  // Pass function references as arguments to higher-order functions.\n  assert(apply_fn(double_it, 7) == 14, \"fn-ref as arg (double)\");\n  assert(apply_fn(negate_it, 3) == -3, \"fn-ref as arg (negate)\");\n\n  // Lambdas with map, filter, and reduce.\n  // Use |...| short form — types are inferred from the call site.\n  nums = [1, 2, 3, 4, 5];\n  doubled = map(nums, |x| { x * 2 });\n  assert(doubled[0] == 2, \"lambda map first element\");\n  assert(doubled[4] == 10, \"lambda map last element\");\n\n  // filter keeps only elements where the lambda returns true.\n  evens = filter(nums, |x| { x % 2 == 0 });\n  assert(evens[0] == 2, \"filter evens first\");\n  assert(evens[1] == 4, \"filter evens second\");\n\n  // reduce collapses the whole list into one value.\n  // The lambda receives the running total (acc) and the next element (x).\n  total = reduce(nums, 0, |acc, x| { acc + x });\n  assert(total == 15, \"reduce sum: {total}\");\n\n  // Use fn(...) long form when you need explicit types — for example\n  // when storing a lambda in a variable or passing it without call-site context.\n  negate = fn(x: integer) -> integer { -x };\n  assert(negate(7) == -7, \"stored lambda: {negate(7)}\");\n  assert(apply_fn(|x| { x * x }, 6) == 36, \"lambda as arg: 6^2\");\n\n  // --- Named arguments ---\n  assert(connect(\"example.com\") == \"example.com:8080:true\", \"all defaults\");\n  assert(connect(\"example.com\", tls: false) == \"example.com:8080:false\", \"skip port\");\n  assert(connect(host: \"example.com\", tls: false) == \"example.com:8080:false\", \"all named\");\n  assert(connect(\"example.com\", port: 443, tls: false) == \"example.com:443:false\", \"mixed\");\n  assert(greet(name: \"World\") == \"Hello, World!\", \"named with default greeting\");\n\n  // --- Default argument that depends on another argument ---\n  // 'end' defaults to len(t), computed from the earlier 't' parameter.\n  assert(substring(\"hello\", 1, 3) == \"el\", \"explicit start and end\");\n  assert(substring(\"hello\", 2) == \"llo\", \"end defaults to len(t)\");\n  assert(substring(\"hello\") == \"hello\", \"both defaults\");\n}",
"vector": "// A vector is an ordered list of values that can grow and shrink while your program runs.\n// Every element must have the same type — you cannot mix integers and text in one vector.\n// Write a vector literal with square brackets: '[1, 2, 3]'.\n// Loft automatically manages the storage, so vectors grow as you add elements\n// without you having to say how large they will be up front.\n// ## Transforming vectors: map, filter, reduce\n// 'map', 'filter', and 'reduce' each take a function and apply it to the vector.\n// Pass the function by writing its NAME on its own — 'map(v, triple)', with no 'fn'\n// in front of it.\n//   map(v, f)          — apply f to every element; returns a new vector\n//   filter(v, pred)    — keep only elements for which pred returns true\n//   reduce(v, init, f) — combine all elements into a single value, starting from init\nfn triple(x: integer) -> integer {\n  x * 3\n}\n\nfn is_even_n(x: integer) -> boolean {\n  x % 2 == 0\n}\n\nfn sum_acc(acc: integer, x: integer) -> integer {\n  acc + x\n}\n\nfn mul_acc(acc: integer, x: integer) -> integer {\n  acc * x\n}\n\nfn set_first_v(v: vector<integer>, x: integer) {\n  v[0] = x;\n}\n\nfn append_one_v(v: vector<integer>, x: integer) {\n  v += [x];\n}\n\nfn replace_all_plain(v: vector<integer>) {\n  v = [7, 7];\n}\n\nfn replace_all(v: &vector<integer>) {\n  v = [7, 7];\n}\n\nfn main() {\n  // Create a vector with a literal and loop over it with 'for'.\n  // Two special loop annotations help when you need to know where you are:\n  //   'v#first'  is true only on the very first iteration — useful for skipping separators.\n  //   'v#index'  holds the zero-based position of the current element.\n  x =[1, 3, 6, 9];\n  b = \"\";\n  for v in x {\n    if !v#first {\n      b += \" \";\n    }\n    b += \"{v#index}:{v}\"\n  }\n  assert(b == \"0:1 1:3 2:6 3:9\", \"result {b}\");\n  // '+=' appends another vector to the end of an existing one.\n  // You can filter and delete elements in a single pass:\n  //   Add 'if condition' after 'in vector' to visit only matching elements.\n  //   Write 'v#remove' inside the loop body to delete the current element.\n  // Here we keep only multiples of 3 by removing everything else.\n  // Note: you cannot append to a vector (v += [...]) while iterating over it —\n  // that is a compile error because the loop would then visit the new elements too,\n  // which could loop forever.\n  x +=[12, 14, 15];\n  for v in x if v % 3 != 0 {\n    v#remove;\n  }\n  assert(\"{x}\" == \"[3,6,9,12,15]\", \"result {x}\");\n  // ## Clearing\n  // 'v.clear()' removes all elements, setting the length to 0.\n  // The underlying storage is kept so appending afterwards is efficient.\n  x.clear();\n  assert(x.len() == 0, \"clear empties the vector\");\n  x += [99];\n  assert(x[0] == 99, \"append after clear works\");\n  // ## Slicing\n  // A slice gives you a window into part of a vector without copying it.\n  // 'v[a..b]' contains elements at positions a, a+1, ..., b-1 (b is excluded).\n  // 'v[a..]'  goes from position a to the very last element.\n  // 'v[..b]'  goes from the beginning up to (but not including) position b.\n  pows =[1, 2, 4, 8, 16];\n  assert(\"{pows[1..3]}\" == \"[2,4]\", \"Sub-vector\");\n  assert(\"{pows[3..]}\" == \"[8,16]\", \"Open-ended sub-vector\");\n  assert(\"{pows[..3]}\" == \"[1,2,4]\", \"Open-start sub-vector\");\n  // Accessing an index that does not exist is safe: Loft returns null instead of crashing.\n  // You can check for null with '!' (logical not) because null is falsy.\n  assert(!pows[10], \"Out-of-bounds access returns null\");\n  // ## Comprehensions\n  // A comprehension is a concise way to build a new vector from a formula.\n  // Syntax: '[for variable in range { expression }]'\n  // Add 'if condition' to include only elements that satisfy the condition.\n  // This is much shorter than creating an empty vector and appending in a loop.\n  evens =[for n in 1..10 if n % 2 == 0 {\n    n\n  }];\n  assert(\"{evens}\" == \"[2,4,6,8]\", \"Filtered comprehension\");\n  doubled =[for n in 1..6 {\n    n * 2\n  }];\n  assert(\"{doubled}\" == \"[2,4,6,8,10]\", \"Doubled comprehension\");\n  // Embedding a for loop directly inside a format string '{...}' produces a formatted list.\n  // The format specifier after ':' is applied to every element in the result.\n  // ':02' means \"at least 2 digits wide, padded with zeros on the left\".\n  assert(\"{for n in 1..7 {n*2}:02}\" == \"[02,04,06,08,10,12]\", \"Formatted vector loop\");\n  // ## Reverse Iteration\n  // Wrap a range in 'rev()' to step through elements from the last index to the first.\n  // 'rev(0..=3)' covers indices 0, 1, 2, 3 — the '=' makes the upper end inclusive.\n  // Here we visit pows[3]=8, pows[2]=4, pows[1]=2, pows[0]=1, building 8421 digit by digit.\n  c = 0;\n  for e in pows[rev(0..=3)] {\n    c = c * 10 + e;\n  }\n  assert(c == 8421, \"Reverse sub-vector iteration\");\n  // You can fill a vector with many copies of the same value using '; count' syntax:\n  //   [SomeStruct { field: value }; 16]\n  // This creates 16 identical copies in one expression. See 08-struct.loft for examples.\n  // ## Passing vectors to functions\n  //\n  // A vector parameter is a shared view of the caller's vector — no data is copied.\n  // So everything the function does to the CONTENTS is visible to the caller once\n  // it returns: writing an element, appending, removing, clearing. You do not need\n  // to mark the parameter for any of that.\n  //\n  // Exactly one thing stays local: replacing the WHOLE value. Writing 'v = [7, 7]'\n  // inside the function gives that function a different vector and leaves the\n  // caller's alone. Mark the parameter '&' when you want that replacement to reach\n  // the caller as well.\n  //\n  //   fn replace_all(v: &vector<integer>) { v = [7, 7]; }   // caller sees the new vector\n  //\n  // So '&' means \"I may replace this\", not \"I may add to it\".\n  //\n  // A SLICE is a different thing again. 'v[2..5]' builds a FRESH vector holding\n  // copies of those elements, so writing to the slice does not reach the original.\n  // A slice is also not accepted where a 'vector<T>' parameter is expected — bind\n  // it to a variable first, and remember you are then working on a copy.\n  passed: vector<integer> = [1, 2, 3];\n  set_first_v(passed, 99);\n  assert(passed[0] == 99, \"a write to an existing element reaches the caller\");\n  grown: vector<integer> = [1, 2, 3];\n  append_one_v(grown, 4);\n  assert(len(grown) == 4, \"…and so does an append, with no '&' needed\");\n  kept: vector<integer> = [1, 2, 3];\n  replace_all_plain(kept);\n  assert(len(kept) == 3, \"replacing the whole value stays inside the function\");\n  swapped: vector<integer> = [1, 2, 3];\n  replace_all(swapped);\n  assert(swapped[0] == 7, \"…unless the parameter is marked '&'\");\n  source: vector<integer> = [1, 2, 3, 4, 5];\n  window = source[2..5];\n  set_first_v(window, 77);\n  assert(window[0] == 77, \"the slice itself is written\");\n  assert(source[2] == 3, \"…and the original is untouched, because a slice is a copy\");\n  // ## Higher-order functions\n  // 'map' applies a function to every element and returns a new vector.\n  nums =[1, 2, 3, 4, 5];\n  tripled = map(nums,  triple);\n  assert(\"{tripled}\" == \"[3,6,9,12,15]\", \"map triple: {tripled}\");\n  // 'filter' keeps only elements for which the predicate returns true.\n  evens2 = filter(nums,  is_even_n);\n  assert(\"{evens2}\" == \"[2,4]\", \"filter evens: {evens2}\");\n  // 'reduce' folds all elements into a single value, starting from an initial accumulator.\n  // Argument order: reduce(vector, initial_value, combiner).\n  total = reduce(nums, 0,  sum_acc);\n  assert(total == 15, \"reduce sum: {total}\");\n  product = reduce(nums, 1,  mul_acc);\n  assert(product == 120, \"reduce product: {product}\");\n  // You can chain these calls: filter first, then map, then reduce.\n  result = reduce(map(filter(nums,  is_even_n),  triple), 0,  sum_acc);\n  assert(result == 18, \"filter+map+reduce: {result}\");\n}",
"structs": "// A struct groups related values under one name. Instead of keeping a\n// product's name, price, and stock count in three separate variables that\n// can drift out of sync, you bundle them together into a Product struct.\n// Each piece of data inside the struct is called a field. You read and write\n// fields using dot notation: 'product.price'.\n// Here is a simple product record. All four fields are plain integers or text.\nstruct Product {\n  name: text,\n  price: integer,\n  stock: integer\n}\n// ## Field Constraints\n// You can restrict what values a field may hold.\n// 'limit(min, max)' gives the field a smaller range. It is not a rejection and it\n// never stops your program: a value outside the range cannot be represented, so the\n// field takes the same answer any uncomputable number takes (see the Integers page).\n// That is null when the field is nullable, and the type's default when it is not —\n// 0 for a range that includes zero.\n// Zero is an ordinary value here. A Colour of 0, 0, 0 is pure black and reads back\n// as three zeros, with nothing extra to write.\n// Fields you omit in a constructor receive zero (or null for nullable fields) by default.\n//\n// You may meet 'not null' on a field in older code. It has no effect — a type is\n// non-null by default now — and the compiler advises removing it.\n\nstruct Colour {\n  r: integer limit(0, 255),\n  g: integer limit(0, 255),\n  b: integer limit(0, 255)\n}\n// ## Methods\n// A method is a function whose first parameter is named 'self'.\n// Loft uses the type of 'self' to decide which struct the method belongs to.\n// Call it with dot notation: 'c.to_hex()'.\n// A method can read fields via 'self.field' and return any type.\n\nfn to_hex(self: Colour) -> integer {\n  self.r * 0x10000 + self.g * 0x100 + self.b\n}\n// A method can also return a completely new struct value.\n// Write '-> StructName' as the return type and construct the value in the body.\n// The original struct is not modified — the caller gets a brand-new copy.\n\nfn dimmed(self: Colour) -> Colour {\n  Colour {r: self.r / 2, g: self.g / 2, b: self.b / 2 }\n}\n// ## Defaults and Computed Fields\n// Write '= expression' after the type to set a stored default, filled at construction.\n// Use 'computed(expression)' for a field that recalculates every time you read it —\n// it takes no space in the record and always reflects the current state.\n// Inside both, '$' refers to the struct.\n\nstruct Item {\n  name: text,\n  name_length: integer = len($.name)\n}\n\nstruct Circle {\n  radius: float,\n  area: float computed(3.14159265 * $.radius * $.radius)\n}\n// ## Storing many structs in a vector\n// 'Area' uses smaller integer types to save memory: 'u16' holds values 0–65535,\n// and 'u8' holds values 0–255. This matters when you have millions of records\n// (such as tiles in a game map) and memory usage counts.\n\nstruct Area {\n  height: u16,\n  terrain: u8,\n  water: u8,\n  direction: u8\n}\n// ## Value structs\n// Prefix a struct with 'value' to give it value (copy) semantics and zero heap\n// overhead: it is stored inline inside a record or vector element, exactly like\n// a plain integer. Reading one out of a field or element yields an independent\n// COPY — writing to that copy never changes the original. Use a 'value struct'\n// for small wrapper types (a point, a colour, a timestamp) that should be as\n// cheap as the number they wrap.\n//\n// A plain (reference) struct differs only when you read one OUT of somewhere.\n// Two spellings look alike, so it is worth keeping them apart:\n//\n// * Binding a whole value COPIES it, always. After 'b = a' the two names are\n//   independent, and writing 'b' never changes 'a'. The copy goes all the way\n//   down, including nested structs and vectors.\n// * Reading a struct-typed field or element gives you a VIEW: 'w = o.inner'\n//   and 'c = v[i]' name the record in place, so 'w.n = 42' changes 'o.inner'\n//   too. A view is not a copy — it points at the interior of what you read it\n//   from. (A vector-typed field is a whole value, so 'av = bx.v' copies.)\n// * Write '&' when you want a live link where a bind would copy: 'b = &a' and\n//   'av = &bx.v' both write through to the source.\n// * ⚠ The same expression can COPY in one position and ALIAS in another. 'av = bx.v'\n//   copies, because binding a whole value always copies — but 'f(bx.v)' hands the\n//   field itself to the function, and a heap parameter shares what it is given (see\n//   the Vector page), so the function writes through to 'bx.v'. Binding is the copy;\n//   passing is not. Read the position, not just the expression.\n\nvalue struct Point {\n  x: integer,\n  y: integer\n}\n\nstruct Holder8 {\n  v: vector<integer>\n}\n\nfn touch8(w8: vector<integer>) {\n  w8[0] = 99;\n}\n\nfn main() {\n  // Constructing a struct: name the fields you want to set.\n  // Fields you leave out default to zero (or null for nullable fields).\n  apple = Product {name: \"Apple\", price: 120, stock: 50 };\n  assert(apple.price == 120, \"price field: {apple.price}\");\n  assert(apple.name == \"Apple\", \"name field: {apple.name}\");\n  // You can read and write individual fields after construction.\n  apple.stock -= 1;\n  assert(apple.stock == 49, \"stock after one sale: {apple.stock}\");\n  // A field omitted from the constructor gets zero as its default. loft points this\n  // out ('omitted-field-zero'): the zero is the type's, and nothing in the\n  // declaration chose it. That is fine when zero is what you meant, and a trap when\n  // zero is a meaningful value in your data — an index where 0 is the first entry,\n  // say. Give the field a declared default when you want a different one, the way\n  // 'Item.name_length' does above.\n  col = Colour {r: 128, b: 128 };\n  assert(col.g == 0, \"omitted green channel defaults to zero\");\n  // Zero is a real value in a limited field — pure black needs nothing extra.\n  black = Colour {r: 0, g: 0, b: 0 };\n  assert(black.r == 0 and black.g == 0 and black.b == 0, \"pure black reads back as zeros\");\n  // A value outside the range takes the type's default rather than being rejected.\n  over = 300;\n  black.r = over;\n  assert(black.r == 0, \"out of range takes the default: {black.r}\");\n  // Formatting a struct shows all fields compactly.\n  assert(\"{col}\" == \"{{r:128,g:0,b:128}}\", \"Struct compact formatting\");\n  // ':j' produces JSON output — a text format used by many web APIs and config tools.\n  assert(\"{col:j}\" == \"{{\\\"r\\\":128,\\\"g\\\":0,\\\"b\\\":128}}\", \"JSON format\");\n  // Call a method on a variable using dot notation.\n  purple = Colour {r: 128, b: 128 };\n  assert(\"{purple.to_hex():x}\" == \"800080\", \"hex method result\");\n  // You can call a method directly on a constructor expression.\n  assert(Colour {r: 255, g: 0, b: 0 }.to_hex() == 0xff0000, \"method on constructor\");\n  // 'dimmed' returns a new Colour with each channel halved.\n  // The original variable is unchanged.\n  dark = purple.dimmed();\n  assert(dark.r == 64, \"dimmed r: {dark.r}\");\n  assert(dark.b == 64, \"dimmed b: {dark.b}\");\n  assert(dark.g == 0, \"dimmed g: {dark.g}\");\n  // Stored defaults are filled once at construction time.\n  it = Item {name: \"hello\" };\n  assert(it.name_length == 5, \"stored default name_length: {it.name_length}\");\n  // computed() fields recalculate on every access — changing radius updates area.\n  ci = Circle { radius: 5.0 };\n  assert(ci.area > 78.0, \"computed area: {ci.area}\");\n  ci.radius = 10.0;\n  assert(ci.area > 314.0, \"recomputed area: {ci.area}\");\n  // Fill a vector with copies of the same struct using '; count' syntax.\n  // This creates 16 Area records, all with the same initial values.\n  map =[Area {height: 0, terrain: 1, water: 1, direction: 1 };\n  16];\n  assert(\"{map[3]}\" == \"{{height:0,terrain:1,water:1,direction:1}}\", \"tile record\");\n  map[3].height = 200;\n  assert(map[3].height == 200, \"individual tile update\");\n  // A value struct binding is a snapshot (copy), not a shared view.\n  pts =[Point {x: 1, y: 2 }, Point {x: 3, y: 4 }];\n  q = pts[0];\n  // q is an independent COPY of element 0\n  q.x = 99;\n  assert(pts[0].x == 1, \"value struct copy does not write back\");\n  assert(q.x == 99, \"the copy itself did change\");\n  // A PLAIN struct answers the same two questions differently, so here they are\n  // side by side. Reading one out of an element gives a view, and writing the\n  // view reaches the element.\n  shelf =[Product {name: \"Pear\", price: 90, stock: 10 }];\n  item = shelf[0];\n  item.stock = 7;\n  assert(shelf[0].stock == 7, \"a plain struct element read is a view\");\n  // Binding the whole value copies it, so the original keeps its own stock.\n  spare = item;\n  spare.stock = 3;\n  assert(item.stock == 7, \"a whole-value bind copies\");\n  assert(spare.stock == 3, \"and the copy moves on its own\");\n  // The same field expression, in the two positions: bound it copies, passed it does\n  // not. This pair is easy to generalise the wrong way in either direction.\n  bx8 = Holder8 { v: [1, 2, 3] };\n  av8 = bx8.v;\n  av8[0] = 42;\n  assert(bx8.v[0] == 1, \"binding a vector field copies it\");\n  cx8 = Holder8 { v: [1, 2, 3] };\n  touch8(cx8.v);\n  assert(cx8.v[0] == 99, \"passing the same field shares it\");\n  // Write '&' to get a live link where a bind would otherwise copy.\n  linked = &item;\n  linked.stock = 1;\n  assert(item.stock == 1, \"'&' binds a live link\");\n  // ## sizeof\n  // 'sizeof(Type)' returns the packed byte size used when the type is stored\n  // as a struct field or vector element. Range-constrained integer types like\n  // u8 and u16 report their packed size, not the 4-byte stack slot size.\n  assert(sizeof(integer) == 8, \"integer: 8 bytes (post-2c i64 storage)\");\n  assert(sizeof(u8) == 1, \"u8: 1 byte (packed)\");\n  assert(sizeof(u16) == 2, \"u16: 2 bytes (packed)\");\n  assert(sizeof(Colour) == 3, \"Colour: 3 × u8 = 3 bytes\");\n  assert(sizeof(Area) == 5, \"Area: u16 + 3 × u8 = 5 bytes\");\n}",
"enums": "// An enum defines a fixed set of named choices. Instead of using raw numbers\n// like 0 = north, 1 = east — which nobody can read six months later — you give\n// each option a name. The compiler then checks every comparison and conversion,\n// so a typo becomes a compile error instead of a silent wrong answer.\n// Plain enums are just names that can be compared, ordered, and converted\n// to and from text. Their order matches their declaration order.\nenum Direction {\n  North,\n  East,\n  South,\n  West\n}\n// ## Enums that carry data\n// Sometimes different choices have different shapes of data.\n// A 'Circle' needs one number (radius); a 'Rect' needs two (width and height).\n// Struct enums let each variant carry its own fields, keeping all the shape\n// kinds in one type while still letting you work with each variant naturally.\n\nenum Shape {\n  Circle {radius: float },\n  Rect {width: float, height: float }\n}\n// ## Methods that work on any variant\n// Write the same function name for each variant, each taking 'self' of that\n// variant's type. Loft automatically picks the right version at runtime based\n// on which variant is actually stored in the variable.\n// This lets you call shape.area() without caring which kind of shape it is.\n\nfn area(self: Circle) -> float {\n  PI * pow(self.radius, 2)\n}\n\nfn area(self: Rect) -> float {\n  self.width * self.height\n}\n// Polymorphic methods can return text just as well as numbers.\n// Each variant can produce its own human-readable description.\n\nfn describe(self: Circle) -> text {\n  \"circle with radius {self.radius}\"\n}\n\nfn describe(self: Rect) -> text {\n  \"rect {self.width} by {self.height}\"\n}\n// ## Enum methods\n// Plain enum variants can also have methods. The 'self' parameter carries the\n// current direction value, and the method can return any type.\n// Here 'opposite()' flips North↔South and East↔West.\n\nfn opposite(self: Direction) -> Direction {\n  if self == North {\n    South\n  } else if self == South {\n    North\n  } else if self == East {\n    West\n  } else {\n    East\n  }\n}\n\nfn main() {\n  // Plain enum values are ordered by declaration position.\n  // North comes first (smallest), West comes last (greatest).\n  d = Direction.East;\n  assert(d == East, \"Enum equality\");\n  assert(d != North, \"Enum inequality\");\n  assert(d > North, \"East declared after North, so it is greater\");\n  assert(Direction.West > South, \"West declared last, so it is greatest\");\n  // Convert between text and enum in both directions.\n  assert(\"{d}\" == \"East\", \"Format plain enum as text\");\n  assert(\"West\" as Direction == West, \"Parse text to enum\");\n  // Use a plain enum method like any other method.\n  assert(d.opposite() == West, \"opposite of East is West\");\n  assert(Direction.North.opposite() == South, \"opposite of North is South\");\n  // Struct enum variants are constructed exactly like regular structs.\n  c = Circle {radius: 1.0 };\n  assert(c.radius == 1.0, \"Circle radius field\");\n  r = Rect {width: 4.0, height: 5.0 };\n  assert(r.width * r.height == 20.0, \"Rect manual area\");\n  // Calling area() on a Circle runs the Circle version;\n  // on a Rect it runs the Rect version — chosen automatically at runtime.\n  assert(round(c.area() * 1000) == round(PI * 1000), \"Circle area = PI*r^2\");\n  assert(r.area() == 20.0, \"Rect area = width*height\");\n  // describe() uses format strings with field access inside each variant's method.\n  assert(c.describe() == \"circle with radius 1\", \"describe circle: {c.describe()}\");\n  assert(r.describe() == \"rect 4 by 5\", \"describe rect: {r.describe()}\");\n  // ## Stubs for missing implementations\n  // If a variant intentionally has no implementation of a method, the compiler\n  // emits a warning (\"no implementation of 'area' for variant 'Rect'\"). Provide an\n  // empty-body stub to silence it:\n  //   fn area(self: SomeVariant) -> float { }\n  // Give the stub a real body — '{ 0.0 }' — when anything reads its result. An\n  // empty body silences the warning and hands back the type's default (0.0 for a\n  // float, 0 for an integer, \"\" for text), which is the same on both backends.\n  // That is a real value, not a marker: it is not null, so there is nothing to\n  // test for, and a caller cannot tell it from a computed 0.0.\n\n  // ## Match expressions on enums\n  // Match picks a code path based on the active variant. You must handle\n  // every variant, or include a `_` wildcard arm that catches the rest.\n  axis = match d {\n    North | South => \"vertical\",\n    East | West => \"horizontal\"\n  };\n  assert(axis == \"horizontal\", \"or-pattern: East matches East|West\");\n\n  // When a variant has fields, name them inside braces to use them in the arm body.\n  label = match c {\n    Circle { radius } => \"r={radius}\",\n    Rect { width, height } => \"{width}x{height}\"\n  };\n  assert(label == \"r=1\", \"field destructuring in match arm\");\n\n  // ## Guard clauses\n  // An arm can have an `if` guard after the pattern. If the guard fails,\n  // matching falls through to the next arm. Because the guard can fail,\n  // a guarded arm alone does not prove the variant is handled — you still\n  // need a wildcard `_` or an unguarded arm for that variant.\n  area = match c {\n    Circle { radius } if radius > 0.0 => PI * radius * radius,\n    _ => 0.0\n  };\n  assert(round(area * 1000) == round(PI * 1000), \"guarded match on Circle\");\n\n  // ## Scalar match\n  // Match also works on integers, text, floats, booleans, and characters.\n  // Arms can be literals, ranges, `null`, or `_`.\n  grade = match 85 {\n    90..=100 => \"A\",\n    80..90   => \"B\",\n    _        => \"C\"\n  };\n  assert(grade == \"B\", \"range pattern 80..90 matches 85\");\n\n  // Or-patterns work on scalars too.\n  kind = match 2 {\n    1 | 2 | 3 => \"low\",\n    _         => \"high\"\n  };\n  assert(kind == \"low\", \"scalar or-pattern\");\n\n  // A `null` pattern matches when the value is absent — here a division by zero,\n  // which yields null (see the Integers page). The `?? null` turns the reasoned\n  // null into a plain one; it is the value that is being matched either way.\n  zero = 0;\n  check = match 1 / zero ?? null {\n    null => \"absent\",\n    _    => \"present\"\n  };\n  assert(check == \"absent\", \"null pattern matches div-by-zero when defended\");\n\n  // Character literals work in match arms.\n  vowel = match 'e' {\n    'a' | 'e' | 'i' | 'o' | 'u' => true,\n    _ => false\n  };\n  assert(vowel, \"character or-pattern\");\n}",
"sorted": "// A 'sorted' collection holds records in order by one or more fields you choose\n// as the sort criteria (called \"key fields\"). You can look up a record by those\n// fields instantly and iterate all records in that order.\n// The collection stays sorted as you add new elements — no manual sorting needed.\n// Declare the key fields inside angle brackets: 'field' sorts A→Z / 0→9 (ascending),\n// '-field' sorts Z→A / 9→0 (descending).\nstruct Elm {\n  key: text,\n  value: integer\n}\n\nstruct Db {\n  map: sorted < Elm[-key] >\n}\n\n// `-key`, and answers a lookup by that key\nfn main() {\n  // ## Adding Elements\n  // You initialise a sorted collection the same way as a vector.\n  // The elements are automatically placed in the right position as you add them.\n  db = Db {map: [\n  Elm {key: \"One\", value: 1 },\n  Elm {key: \"Two\", value: 2 },\n  Elm {key: \"Three\", value: 3 },\n  Elm {key: \"Four\", value: 4 }\n  ] };\n  // ## Looking Up by Key\n  // Use square brackets with the key value to find a record instantly.\n  // If the key is not present the result is null — you can check it with '!'.\n  assert(db.map[\"Two\"].value == 2, \"Key lookup: Two\");\n  assert(db.map[\"Three\"].value == 3, \"Key lookup: Three\");\n  assert(!db.map[\"Five\"], \"Missing key returns null\");\n  assert(!db.map[null], \"Null key returns null\");\n  // Append new elements with '+='; they are placed in the correct sorted position.\n  db.map +=[Elm {key: \"Zero\", value: 0 }];\n  assert(db.map[\"Zero\"].value == 0, \"Newly added element\");\n  // ## Iterating in Order\n  // A 'for' loop over a sorted collection visits elements in key order.\n  // Here the key is '-key' (descending text), so the order is: Zero, Two, Three, One, Four.\n  sum = 0;\n  for v in db.map {\n    sum = sum * 10 + v.value;\n  }\n  // Zero(0), Two(2), Three(3), One(1), Four(4) → 0*10+2=2, *10+3=23, *10+1=231, *10+4=2314\n  assert(sum == 2314, \"Sorted iteration total: {sum}\");\n  // ## Iterating in Reverse\n  // Wrap the collection in rev() to visit elements from last to first key order.\n  // Here the collection is sorted by '-key' (descending text), so the stored order is\n  // Zero, Two, Three, One, Four.  rev() visits them in the opposite order.\n  rev_sum = 0;\n  for v in rev(db.map) {\n    rev_sum = rev_sum * 10 + v.value;\n  }\n  // Four(4), One(1), Three(3), Two(2), Zero(0) → 4*10+1=41, *10+3=413, *10+2=4132, *10+0=41320\n  assert(rev_sum == 41320, \"Reverse iteration total: {rev_sum}\");\n  // ## Loop Helpers: #first, #count, #index, and #remove\n  // 'v#first' is true for the very first element visited.\n  // 'v#count' is a running index starting at 0.\n  // 'v#index' is a sequential counter over the visited elements, also starting\n  // at 0 — on a sorted collection it advances in step with '#count'.\n  // 'v#remove' removes the current element while iterating.\n  first_key = \"\";\n  labels = \"\";\n  index_sum = 0;\n  for v in db.map {\n    if v#first {\n      first_key = v.key\n    }\n    if !v#first {\n      labels += \",\"\n    }\n    // '#index' matches '#count' here: both run 0,1,2,3,4 over the five elements.\n    assert(v#index == v#count, \"index tracks count: {v#index} vs {v#count}\");\n    index_sum += v#index;\n    labels += \"{v#count}:{v.key}\"\n  }\n  assert(first_key == \"Zero\", \"First element: {first_key}\");\n  assert(labels == \"0:Zero,1:Two,2:Three,3:One,4:Four\", \"Labels: {labels}\");\n  assert(index_sum == 10, \"0+1+2+3+4 = {index_sum}\");\n  // Remove elements with value > 2 while iterating.\n  for v in db.map if v.value > 2 {\n    v#remove\n  }\n  sum2 = 0;\n  for v in db.map {\n    sum2 += v.value\n  }\n  // Remaining: Zero(0), Two(2), One(1) → sum = 3\n  assert(sum2 == 3, \"Sum after remove: {sum2}\");\n  // ## Removing by Key\n  // Assigning null to a sorted subscript removes the element with that key.\n  // Removing a key that is not present is a safe no-op.\n  db2 = Db {map: [\n  Elm {key: \"A\", value: 10 },\n  Elm {key: \"B\", value: 20 },\n  Elm {key: \"C\", value: 30 }\n  ] };\n  db2.map[\"B\"] = null;\n  assert(!db2.map[\"B\"], \"B was removed\");\n  assert(db2.map[\"A\"].value == 10, \"A still present\");\n  assert(db2.map[\"C\"].value == 30, \"C still present\");\n  db2.map[\"missing\"] = null;\n  // no-op; does not panic\n  sum3 = 0;\n  for v in db2.map {\n    sum3 += v.value\n  }\n  assert(sum3 == 40, \"Sum after key removal: {sum3}\");\n  // Note: '#index' works on a sorted collection — it is a sequential counter that\n  // advances one per visited element (see the loop above). It is only 'index<T>'\n  // collections that reject '#index' — use '#count' there instead (see 11-index).\n  // ## Iterating a Key Range\n  // The range examples live in `main_ranges` below; run them here, because a file\n  // with a `main` runs only its `main`.\n  main_ranges();\n}\n\nstruct Word {\n  name: text,\n  score: integer\n}\n\nstruct Dict {\n  words: sorted<Word[name]>\n}\n\nfn main_ranges() {\n  // ## Iterating a Key Range\n  // Give the collection a RANGE in square brackets and the loop starts and stops at\n  // the right places, without looking at the records outside it. This is the operation\n  // a sorted collection exists for.\n  //   c[lo..hi]   from lo up to but NOT including hi\n  //   c[lo..=hi]  from lo up to AND including hi\n  //   c[lo..]     from lo to the end\n  //   c[..hi]     from the start up to but not including hi\n  // Mind the two spellings: '..' leaves the last key out, '..=' keeps it. That is the\n  // same rule as a vector slice.\n  d = Dict { words: [\n    Word { name: \"apple\",      score: 5 },\n    Word { name: \"banana\",     score: 3 },\n    Word { name: \"cherry\",     score: 8 },\n    Word { name: \"date\",       score: 2 },\n    Word { name: \"elderberry\", score: 1 }\n  ] };\n  slice_total = 0;\n  for w in d.words[\"banana\"..=\"date\"] {\n    slice_total += w.score\n  }\n  assert(slice_total == 13, \"banana(3)+cherry(8)+date(2) = {slice_total}\");\n  half_open = 0;\n  for w in d.words[\"banana\"..\"date\"] {\n    half_open += w.score\n  }\n  assert(half_open == 11, \"'..' leaves date out: {half_open}\");\n  head_total = 0;\n  for w in d.words[..\"cherry\"] {\n    head_total += w.score\n  }\n  assert(head_total == 8, \"apple(5)+banana(3) = {head_total}\");\n  // ## Filtering on something that is NOT the key\n  // An `if` guard inside the loop still works, and it is what you want when the\n  // condition is not about the key: the guard sees every element and the body runs\n  // only for the matching ones. Use a range when you are selecting BY key, and a\n  // guard when you are selecting by anything else.\n  cheap = 0;\n  for w in d.words if w.score < 4 {\n    cheap += w.score\n  }\n  assert(cheap == 6, \"banana(3)+date(2)+elderberry(1) = {cheap}\");\n  // ## Open-ended Range (tail)\n  // All records from \"cherry\" onward to the end of the sorted order.\n  tail_count = 0;\n  for w in d.words if w.name >= \"cherry\" {\n    tail_count += 1\n  }\n  assert(tail_count == 3, \"cherry, date, elderberry = {tail_count}\");\n  // ## Open-ended Range (head)\n  // All records up to and including \"banana\".\n  head_names = \"\";\n  for w in d.words if w.name <= \"banana\" {\n    head_names += w.name + \" \"\n  }\n  assert(head_names == \"apple banana \", \"apple and banana: '{head_names}'\");\n  // ## Range outside the for (building a result vector)\n  // Collect matching records into a vector for later use.\n  subset = [for w in d.words if w.name >= \"banana\" && w.name <= \"cherry\" { w.score }];\n  assert(subset[0] == 3, \"first in range: {subset[0]}\");\n  assert(subset[1] == 8, \"second in range: {subset[1]}\");\n}\n// filling and finding values",
"index": "// An 'index' lets you find records instantly by key and iterate over ranges of keys in order.\n// It supports multi-part keys: you can sort by a primary key and break ties with a secondary key.\n// Declare the key fields inside angle brackets: 'field' sorts ascending, '-field' descending.\n//\n// Two keyed collections over the SAME element type are two ROUTES to one set of records, not\n// two collections. Give records to either one and both see them; write through one and the\n// other reads the change; remove through one and it is gone from both. That is the point of\n// declaring a second one — a second way in, by a different key — and loft says so if a\n// literal fills both ('linked-group-double-fill'), because then one record set ends up\n// holding everything they were given.\nstruct Elm {\n  nr: integer,\n  key: text,\n  value: integer\n}\n\nstruct Db {\n  map: index < Elm[nr, -key] >\n}\n\n// second key breaking ties in the other direction\nfn main() {\n  // ## Adding and Looking Up Records\n  // Fill the index just like a vector. Elements are automatically kept in key order.\n  // This index is sorted first by 'nr' (ascending), then by 'key' (descending) for ties.\n  db = Db {map: [\n  Elm {nr: 101, key: \"One\", value: 1 },\n  Elm {nr: 92, key: \"Two\", value: 2 },\n  Elm {nr: 83, key: \"Three\", value: 3 },\n  Elm {nr: 83, key: \"Four\", value: 4 },\n  Elm {nr: 83, key: \"Five\", value: 5 },\n  Elm {nr: 63, key: \"Six\", value: 6 }\n  ] };\n  // Provide all key fields together inside brackets to find a record.\n  // Supply fewer fields to match all records that share a prefix.\n  assert(db.map[101, \"One\"].value == 1, \"Key lookup\");\n  assert(!db.map[12, \"\"], \"Missing key returns null\");\n  assert(!db.map[83, \"One\"], \"Wrong secondary key returns null\");\n  // Fewer fields than the key has: every record sharing that prefix.\n  prefix_sum = 0;\n  for r in db.map[83] {\n    prefix_sum += r.value\n  }\n  assert(prefix_sum == 12, \"the three nr=83 records: {prefix_sum}\");\n  // ## Iterating in Order\n  // A 'for' loop visits all elements in key order.\n  total = 0;\n  for r in db.map {\n    total += r.value;\n  }\n  assert(total == 21, \"Sum of all values: {total}\");\n  // ## Range Queries\n  // Provide a range in the first key position to visit only the matching slice.\n  // '[83..92, \"Two\"]' means: nr from 83 up to (not including) 92, and key from \"Two\" down\n  // (since the key is sorted descending, \"Two\" is the start of that descending segment).\n  sum = 0;\n  for v in db.map[83..92, \"Two\"] {\n    sum = sum * 10 + v.value;\n  }\n  // Elements matched: (83, Three, 3), (83, Four, 4), (83, Five, 5)\n  assert(sum == 345, \"Range iteration result: {sum}\");\n  // ## Loop Helpers: #first and #count\n  // 'r#first' is true for the very first element visited.\n  // 'r#count' is a running counter starting at 0.\n  // Note: #index is not meaningful on index collections — use #count instead.\n  first_nr = 0;\n  count_total = 0;\n  for r in db.map {\n    if r#first {\n      first_nr = r.nr\n    }\n    count_total = r#count\n  }\n  assert(first_nr == 63, \"First element by key: {first_nr}\");\n  assert(count_total == 5, \"Total elements: {count_total}\");\n  // ## Removing by Key\n  // Assigning null to an index subscript removes the element with that exact key combination.\n  // Removing a key that is not present is a safe no-op.\n  db.map[92, \"Two\"] = null;\n  assert(!db.map[92, \"Two\"], \"element (92, Two) was removed\");\n  assert(db.map[101, \"One\"].value == 1, \"element (101, One) still present\");\n  db.map[999, \"Z\"] = null;\n  // no-op; does not panic\n  total2 = 0;\n  for r in db.map {\n    total2 += r.value\n  }\n  assert(total2 == 19, \"Sum after key removal: {total2}\");\n}",
"hash": "// A 'hash' lets you find a record by its key in the same time whether you have 10 records or\n// 10 million — there is no searching through a list, just a direct jump to the answer.\n// Unlike 'sorted' and 'index', a hash does not keep its records in order — that is exactly what\n// makes the lookup fast. You can still iterate one and get a predictable order (ascending key),\n// but the hash has to sort a snapshot to do it; see 'Iterating a Hash' at the bottom of this page.\n// List the key fields in brackets: 'hash<Type[field]>'.\n// Combine a hash with a vector when you want both fast lookup and a stable iteration order.\nstruct Keyword {\n  name: text\n}\n\nstruct Data {\n  h: hash < Keyword[name] >\n}\n// ## Combining Hash and Vector\n// Pairing a hash with a vector on the same record type gives you the best of both worlds:\n// the hash for instant lookup by key, and the vector for iterating in insertion order.\n\nstruct Count {\n  t: text,\n  v: integer\n}\n\nstruct Counting {\n  entries: vector < Count >,\n  lookup: hash < Count[t] >\n}\n\nfn fill(c: Counting) {\n  c.entries =[\n {t: \"One\", v: 1 },\n {t: \"Two\", v: 2 },\n {t: \"Three\", v: 3 },\n {t: \"Four\", v: 4 }\n  ]\n}\n\nfn main() {\n  // ## Basic Lookup\n  // Fill a hash the same way you fill a vector. Look up by key with square brackets.\n  // A found record is truthy; a missing key returns null.\n  d = Data { };\n  d.h =[ {name: \"one\" }, {name: \"two\" }];\n  d.h +=[ {name: \"three\" }, {name: \"four\" }];\n  assert(d.h[\"three\"], \"Key exists\");\n  assert(!d.h[\"None\"], \"Missing key returns null\");\n  // ## Hash + Vector Together\n  // Here 'entries' is the vector (keeps insertion order) and 'lookup' is the hash (fast access).\n  // Both fields point to the same records — adding to one automatically updates the other.\n  c = Counting { };\n  fill(c);\n  assert(c.lookup[\"Three\"].v == 3, \"Hash lookup: Three\");\n  assert(c.lookup[\"One\"].v == 1, \"Hash lookup: One\");\n  assert(!c.lookup[\"Five\"], \"Missing key returns null\");\n  // Iterate in insertion order via the vector; look up by name via the hash.\n  // The vector also supports #first, #count, and #remove inside the loop.\n  add = 0;\n  for item in c.entries {\n    add += item.v;\n  }\n  assert(add == 10, \"Sum via vector iteration: {add}\");\n  // ## Removing a Key\n  // Assigning null to a hash subscript removes that element.\n  // Removing a key that is not present is a safe no-op.\n  d.h[\"three\"] = null;\n  assert(!d.h[\"three\"], \"three was removed\");\n  assert(d.h[\"one\"], \"one still present\");\n  d.h[\"missing\"] = null;\n  assert(d.h[\"one\"], \"removing a key that is not there leaves the others alone\");\n  // ## Iterating a Hash\n  // `for e in h { ... }` walks the hash in ascending key order.  The loop\n  // variable has the same shape as a `sorted<T>` iteration — a `reference<T>`\n  // with `#index`, `#count`, and `#first` available.  Multi-field keys sort\n  // lexicographically.\n  //\n  // Under the hood the compiler builds a one-shot sorted snapshot of the\n  // hash's record-numbers and walks it, so iteration cost is\n  // O(n) + O(n log n) per `for`, not amortised across calls.  For a hot\n  // loop, pair the hash with a `vector<T>` or `sorted<T[k]>` on the same\n  // record type and iterate the companion collection.\n  //\n  // `e#remove` is rejected at compile time — the snapshot is detached from\n  // the hash, so removing from it would not actually remove from the hash.\n  // Use `h[key] = null` to remove an entry.\n  // Adding the values up cannot show you the order — a sum is the same whichever way you walk.\n  // Collect the keys instead: they come out alphabetically, not in the order they went in.\n  sum = 0;\n  order = \"\";\n  for e in c.lookup { sum += e.v; order += \"{e.t} \"; }\n  assert(sum == 10, \"Sum via hash iteration: {sum}\");\n  assert(order == \"Four One Three Two \", \"hash walks in key order: {order}\");\n}",
"file": "// A file handle lets you read and write files without worrying about when the\n// OS opens or closes them. The file opens on the first read or write and\n// closes automatically when the handle goes out of scope.\n// ## Inspecting the File System\n// `file(path)` creates a File handle without opening anything yet.\n// `f#format` tells you what kind of path you are looking at: TextFile (plain text),\n// LittleEndian (binary, bytes stored least-significant first — common on most PCs),\n// BigEndian (binary, bytes stored most-significant first — common in network protocols),\n// Directory, or NotExists.\n// `lines()` reads a text file and returns it as a vector of lines.\n// `exists(path)` is a convenience shorthand for checking that a path is not\n// NotExists. `delete(path)` removes a file and returns a `FileResult` enum;\n// use `.ok()` to check success.\n// Clean up any leftover files from a previous interrupted run.\n// `#cwd` opts this program into cwd-relative paths (CLI-tool semantics): a\n// relative path resolves against the working directory, not the program's own\n// directory.  Without it, relative paths re-home next to the program (the\n// portable-bundle default) — see @PLN9.\n#cwd\nfn cleanup() {\n  delete(\"test.bin\");\n  delete(\"test2.bin\");\n  delete(\"buffer.bin\");\n}\n\nstruct Buffer {\n  size: i32,\n  data: vector < single >\n}\n\nfn main() {\n  cleanup();\n  // Asking for the format of a directory path returns Directory, not a file\n  // format. `lines()` reads the named text file and splits it on newlines.\n  ex = file(\"tests/example\");\n  assert(ex#format == Directory, \"example is a directory\");\n  c = file(\"tests/example/config/terrain.txt\").lines();\n  assert(c[1] == \"    terrain = [\", \"Line was '{c[1]}'\");\n  // `exists` and `delete` are safe to call when the file is absent.\n  // `delete` returns false rather than crashing when nothing is there.\n  assert(!exists(\"test.bin\"), \"File should not exist before the test.\");\n  assert(!delete(\"nonexistent_xyz.bin\").ok(), \"delete on missing file not ok\");\n  // ## Writing a Text or Binary File\n  // Wrapping the file handle in a block ensures the file closes the moment\n  // the block ends. Set `f#format` to LittleEndian or BigEndian before\n  // writing binary data. Use `f += value` to append the raw bytes of any\n  // scalar value (u8, u16, i32, integer, single, float, or text). An `integer`\n  // is 8 bytes wide (see the size assertions below).\n {f = file(\"test.bin\");\n  assert(f#format == NotExists, \"File should not exist yet.\");\n  f#format = BigEndian;  // BigEndian: most-significant byte written first.\n  f += 0 as u8;\n  f += 1 as u8;\n  f += 0x203 as u16;\n  f += 0x4050607;\n  f += 0x8090a0b0c0d0e0f;\n  // `f#size` returns the total number of bytes written so far.\n  // Post-2c: integer is 8 bytes, so total = 1 + 1 + 2 + 8 + 8 = 20.\n  assert(f#size == 20, \"Should have written 20 bytes.\");\n  // Text is written as raw UTF-8 bytes with no length prefix.\n  f += \"Hello world!\";\n  assert(f#size == 32, \"Size should be 32 bytes (20 + 12).\");\n }  // The file closes when the handle goes out of scope.\n  // `move(src, dst)` renames a file. It refuses if the destination already\n  // exists.\n  assert(exists(\"test.bin\"), \"File should exist after writing.\");\n  assert(move(\"test.bin\", \"test2.bin\").ok(), \"Could not move the file.\");\n  // ## Reading Back What You Wrote\n  // When you open an existing file the default format is TextFile. Set\n  // `f#format` to match the format used when writing before you read any\n  // bytes. `f#read(n) as T` reads exactly n bytes and interprets them as\n  // type T. `f#index` is the byte offset where the last read started.\n  // `f#next` is the current read position; assign to it to seek anywhere.\n {f = file(\"test2.bin\");\n  assert(f#format == TextFile, \"The default format is TextFile.\");\n  f#format = LittleEndian;\n  // The file was written as BigEndian, so reading the same 4 bytes as\n  // LittleEndian produces a byte-swapped value — that is intentional here\n  // and confirms that the bytes were stored in the order you chose.\n  v = f#read(4) as i32;\n  assert(v == 0x3020100, \"BigEndian bytes 0..3 read as LittleEndian i32.\");\n  assert(f#index == 0, \"Last read started at byte 0.\");\n  assert(f#next == 4, \"Next read starts at byte 4.\");\n  // Seek to byte 20 to skip past the integers and read the text directly.\n  // (Post-2c: i32+i64 header = 1+1+2+8+8 = 20 bytes before the text.)\n  f#next = 20;\n  s = f#read(5) as text;\n  assert(s == \"Hello\", \"Partial text read from offset 20.\");\n  assert(f#index == 20, \"Last read started at byte 20.\");\n  assert(f#next == 25, \"Next position after 5-byte text read.\");\n  // Requesting more bytes than remain simply returns whatever is left.\n  rest = f#read(100) as text;\n  assert(rest == \" world!\", \"Read continues to end of file.\");\n  assert(f#next == f#size, \"Position should be at end of file.\");\n  // You can seek back to any position and re-read.\n  f#next = 0;\n  assert(f#read(4) as i32 == 0x3020100, \"Seek-and-reread matches original.\");\n }\n  assert(delete(\"test2.bin\").ok(), \"Could not remove the test file.\");\n  // ## Working with Vectors and Struct Data\n  // `f += vector<T>` writes every element in sequence as raw bytes, which is\n  // the fastest way to dump a whole collection to disk. Setting `f#size = n`\n  // truncates or zero-extends the file to exactly n bytes — useful for\n  // discarding the tail after you have finished writing.\n {f = file(\"buffer.bin\");\n  f#format = LittleEndian;\n  ints =[1, 2, 3, 4];\n  f += ints;\n  assert(f#size == 32, \"Four integers = 32 bytes (8 each, post-2c)\");\n  // Truncate to the first two integers.\n  f#size = 16;\n  assert(f#size == 16, \"Truncated to 16 bytes\");\n }\n  assert(delete(\"buffer.bin\").ok(), \"Could not remove buffer.bin after vector write test.\");\n  // Write a count followed by individual float values. `sizeof(T)` returns\n  // the byte width of a type, so you can compute the correct read length\n  // without hard-coding magic numbers.\n {buf = file(\"buffer.bin\");\n  buf#format = LittleEndian;\n  buf += 4 as i32;\n  buf += 1.1f;\n  buf += 1.2f;\n  buf += 2.1f;\n  buf += 2.2f;\n }\n  // Read the count, then use it to read exactly that many floats directly\n  // into a struct field. This pattern lets you serialise and deserialise\n  // structs with variable-length data cleanly.  A sized `f#read` answers a\n  // raw byte buffer, so name the type you are reading it back as: the `as`\n  // is what turns those bytes into elements.\n {b = Buffer { };\n  f = file(\"buffer.bin\");\n  f#format = LittleEndian;\n  n = f#read(4) as i32;\n  floats = f#read(n * sizeof(single)) as vector<single>;\n  b.data = floats;\n  assert(len(b.data) == 4, \"Read four floats back into the field.\");\n  assert((b.data[0] ?? 0.0f) == 1.1f, \"First float survives the round-trip.\");\n }\n  assert(delete(\"buffer.bin\").ok(), \"Could not remove buffer.bin.\");\n\n  // ## Error handling\n  // File operations that can fail return a `FileResult` enum.\n  // Call `.ok()` to check success. The program does not crash on failure —\n  // you decide what to do.\n  result = delete(\"this_file_does_not_exist.txt\");\n  assert(!result.ok(), \"delete missing file returns not-ok\");\n\n  // Reading a non-existent file produces an empty result, not a crash.\n  ghost = file(\"no_such_file.txt\");\n  assert(ghost#format == NotExists, \"non-existent file has NotExists format\");\n\n  // `move` reports on the FILES, not on the shape of the path: a missing source\n  // is NotFound whether or not the path contains `..` (loft#712).\n  assert(!move(\"any.txt\", \"../escape.txt\").ok(), \"move with a missing source fails\");\n\n  // Writing to a read-only or invalid path also returns a FileResult.\n  // Always check `.ok()` after `delete`, `move`, `mkdir`, and `mkdir_all`.\n}",
"lexer": "// The lexer library breaks a text into tokens so your program can understand\n// its structure. Tokens are the smallest meaningful pieces: numbers, names\n// (like variable and function names), operators, and quoted strings. You tell\n// the lexer which multi-character sequences count as one token and which words\n// are reserved keywords, and it handles the rest.\n// ## Setting Up the Lexer\n// Create a `lexer::Lexer` and register your language's rules before you parse\n// anything. `set_tokens` ensures operators like `+=` or `>>` are scanned as\n// one token instead of two separate characters. `set_keywords` prevents\n// reserved words from being treated as ordinary names — the lexer will\n// report them exactly as written so your parser can treat them specially.\nuse lexer;\nfn main() {\n  l = lexer::Lexer { };\n  l.set_tokens([\"+=\", \"*=\", \"-=\", \"<=\", \">=\", \"!=\", \"==\", \">>\", \"<<\", \"->\", \"=>\", \">>>\", \"..\", \"..=\", \"&&\", \"||\"]);\n  l.set_keywords([\"for\", \"in\", \"if\", \"else\", \"fn\", \"pub\", \"use\", \"struct\", \"enum\", \"match\", \"and\", \"or\"]);\n  // ## Reading Tokens\n  // `parse_string(name, source)` feeds source text into the lexer. The name\n  // is used in error messages and position reports. After that, call the\n  // typed reader functions one by one to consume tokens in order.\n  //\n  // `int()` consumes and returns the next integer token, or null if the\n  // current token is not an integer. `long_int()` does the same for integers\n  // suffixed with `l`. `matches(s)` consumes the next token only when it\n  // equals s and returns true; otherwise it leaves the token in place and\n  // returns false. `peek()` returns the next token as text without consuming\n  // it. `position()` returns the current location as `file:line:col`.\n  l.parse_string(\"Tokens\", \"12 += -2 * 3 >> 4\");\n  assert(l.int() == 12, \"Integer\");\n  assert(!l.matches(\"+\"), \"Incorrect plus\");\n  assert(l.peek() != \"+\", \"Incorrect plus\");\n  assert(l.matches(\"+=\"), \"Incorrect plus_is\");\n  assert(l.int() == -2, \"Second integer\");\n  assert(l.matches(\"*\"), \"Incorrect multiply\");\n  assert(l.int() == 3, \"Third number\");\n  assert(l.position() == \"Tokens:1:14\", \"Incorrect position {l.position()}\");\n  assert(!l.matches(\">\"), \"Incorrect higher\");\n  assert(l.matches(\">>\"), \"Incorrect logical shift\");\n  assert(l.position() == \"Tokens:1:17\", \"Incorrect position {l.position()}\");\n  // ## String Literals and Comments\n  // `constant_text()` reads a double-quoted string and handles special codes\n  // like \\n (newline) and \\\\ (backslash). `constant_character()` reads a\n  // single-quoted character literal and returns it as text.\n  l.parse_string(\"Texts\", \"\\\"123\\\" + '4'\");\n  assert(l.constant_text() == \"123\", \"Incorrect text literal\");\n  assert(l.matches(\"+\"), \"Incorrect add\");\n  // `constant_character()` returns a `character`, so compare it as one\n  // (`l.constant_character() == '4'`), not against the text \"123\".\n  // The lexer collects `//` comments automatically as it scans. You do not\n  // need to handle them yourself. `last_comment()` returns the accumulated\n  // comment text since the last consumed token. When multiple comment lines\n  // appear in a row they are joined with newlines into a single string.\n  // `comment_behind()` is true when the comment appeared on the same line as\n  // the preceding token rather than on its own line above. `is_finished()`\n  // returns true once every token has been consumed.\n  l.parse_string(\"Comments\", \"// starting comments\\n123 // same line comment\\n// extra comment\\n4\");\n  assert(!l.comment_behind(), \"Initial comment not behind\");\n  assert(l.last_comment() == \"starting comments\", \"Initial comment\");\n  assert(l.int() == 123, \"Content integer\");\n  assert(l.comment_behind(), \"Second comment is behind\");\n  assert(l.last_comment() == \"same line comment\\nextra comment\", \"Second comment\");\n  assert(!l.is_finished(), \"Not Ready\");\n  assert(l.int() == 4, \"Second integer\");\n  assert(l.last_comment() == \"\", \"No remaining comment\");\n  assert(l.is_finished(), \"Ready\");\n  // ## Embedded Format Expressions\n  // Loft string literals can embed expressions with `{expr}`. The lexer\n  // exposes a protocol that lets you parse these yourself. When\n  // `constant_text()` reaches a `{`, it returns the literal text before it\n  // and sets `is_formatting()` to true. At that point call\n  // `set_formatting(false)` and parse the embedded expression normally using\n  // the usual token readers. When the expression is done, call\n  // `set_formatting(true)` and consume the closing `}}`. Then\n  // `constant_text()` continues with the next segment of the string.\n  l.parse_string(\"Formatting\", \"\\\"abc{{12 + 34}}def\\\"\");\n  assert(l.constant_text() == \"abc\", \"Before formatting\");\n  assert(l.is_formatting(), \"Formatting\");\n  l.set_formatting(false);\n  assert(l.int() == 12, \"First integer\");\n  assert(l.matches(\"+\"), \"Incorrect plus\");\n  assert(l.int() == 34, \"Second integer\");\n  l.set_formatting(true);\n  assert(l.matches(\"}}\"), \"Incorrect closing brace\");\n  assert(l.constant_text() == \"def\", \"After formatting\");\n  assert(!l.is_formatting(), \"Formatting\");\n}",
"parser": "// The 'parser' library lets a Loft program read and validate other Loft source\n// code at runtime. This is useful when you want to:\n// * validate configuration files written in the Loft syntax\n// * build tools that inspect or transform Loft source\n// * write a test that checks whether a generated code snippet is syntactically correct\n//\n// Together the 'lexer' and 'parser' libraries are designed as a reusable foundation.\n// You can use them to build entirely new languages: feed the lexer your own token rules,\n// then layer a custom parser on top. This keeps the tokeniser and grammar logic separate\n// from the language runtime so you only bring in what you need.\n//\n// 'parse(name, source)' is the single entry point. It takes a display name\n// (used in error messages) and a Loft source string. The name does not need to\n// correspond to a real file — it is only used when reporting parse errors.\n//\n// If the source is invalid, parse() emits a diagnostic error and the call\n// returns without producing a value.\n// ## What the parser understands\n//\n// The parser handles all Loft syntax:\n// * 'struct Name { field: type [= default] }' — data containers with named fields\n// * 'enum Name { Variant [{ field: type }] }' — named choices, each with optional data\n// * 'fn name(params) [-> type] { body }' — functions with a block body\n// * 'fn name(params) [-> type]; #rust \"template\"' — operator templates backed by Rust\n// * 'use module;' — module imports\n// * Expressions: binary operators with precedence, function calls, field access,\n//   index expressions, if/else, for loops, blocks, and formatted string literals\n// * Type expressions: plain names, generic types like 'vector<T>', keyed\n//   collections (sorted/hash/index), and integer ranges with 'limit(min, max)'\nuse parser;\nfn main() {\n  // ## Parsing a minimal function\n  // The double braces '{{' and '}}' produce literal '{' and '}' inside a\n  // Loft format string — needed here because the source code itself contains braces.\n  assert(parser::parse(\"hello\", \"fn main() {{ println(\\\"Hello World\\\"); }}\") == 0,\n         \"a minimal function parses cleanly\");\n  // ## Parsing a struct and function together\n  // The parser validates the entire source snippet as one unit.\n  // Both the struct definition and the function body are checked.\n  assert(parser::parse(\"point\", \"struct Point {{ x: integer, y: integer }} fn origin() -> Point {{ Point {{ x: 0, y: 0 }} }}\") == 0,\n         \"a struct and a function in one unit parse cleanly\");\n  // ## Parsing an enum\n  // Both a plain variant and a struct variant (with fields) are recognised.\n  assert(parser::parse(\"shape\", \"enum Shape {{ Circle {{ radius: float }}, Rectangle {{ w: float, h: float }} }}\") == 0,\n         \"both a plain and a struct variant parse cleanly\");\n  // ## Parsing several statements in a body\n  // A body is a sequence of statements; each call below is one.\n  assert(parser::parse(\"body\", \"fn m() {{ println(\\\"a\\\"); println(\\\"b\\\"); }}\") == 0,\n         \"a body of several statements parses cleanly\");\n  // ## Parsing assignments and operators\n  // Every binary operator in the table above is accepted, including assignment.\n  assert(parser::parse(\"assign\", \"fn f() {{ t = 0; t += 1; }}\") == 0,\n         \"assignment and compound assignment parse cleanly\");\n  // ## Parsing a for loop and arithmetic\n  // This exercises the expression parser, range syntax, and a tail expression after a\n  // loop body — the shape where a speculative struct-literal parse has to give its\n  // tokens back so the loop can claim them.\n  assert(parser::parse(\"loop\", \"fn sum(n: integer) -> integer {{ t = 0; for i in 1..=n {{ t += i; }} t }}\") == 0,\n         \"a for loop over a range parses cleanly\");\n  // ## Practical use: validating user-supplied code\n  //\n  // If your application lets users write Loft snippets (for scripting or\n  // configuration), you can parse them before executing:\n  //\n  //   snippet = read_user_input();\n  //   if parser::parse(\"user_code\", snippet) > 0 {\n  //     // The snippet was invalid — the count is how many errors it had.\n  //   }\n  //\n  // Combine this with the lexer (see the Lexer page) when you need to extract\n  // individual tokens from the source rather than validate all of the syntax.\n  // ## What a failed parse looks like\n  // The count is the whole point: a snippet that does not parse answers a NON-zero\n  // number, so a caller can tell the two apart. Watching the call not crash cannot.\n  assert(parser::parse(\"broken\", \"fn main() {{ println(\\\"hi\\\");\") > 0,\n         \"an unterminated body reports at least one error\");\n  println(\"parser test passed\");\n}",
"libraries": "// A library is a `.loft` file you can share across projects. Place it in a\n// `lib/` directory, import it with `use name;` at the top of your file, and\n// then refer to its types and functions using the `name::` prefix. All types\n// and functions in a library are accessible — there is no way to mark something\n// as internal or hidden.\n// `use` statements must come before any `fn` or `struct` definition in your\n// file. Putting a `use` after a definition is a syntax error.\nuse testlib;\n// ## Constants and Enums\n// Library constants and enum variants are accessed with the `libname::`\n// prefix. You can compare, order, and convert enum values exactly as you\n// would with enums defined in the same file.\n// ## Struct Construction and Field Access\n// Construct a library struct with its full namespace prefix. Omitting the\n// prefix is a parse error. Once you have a value, field access uses the plain\n// dot notation with no prefix needed.\n// ## Calling Library Methods\n// Methods defined in the library are called on the value directly — no prefix\n// on the call site. Free functions (not methods) do need the `libname::` prefix.\n// ## Extending a Library Type\n// You can add new methods to a library type from your own file. Write the\n// `self` parameter type with the `::` separator and the compiler treats the\n// function as a method on that type.\nfn shifted(self: testlib::Point, dx: float, dy: float) -> testlib::Point {\n  testlib::Point {x: self.x + dx, y: self.y + dy }\n}\n\nfn main() {\n  // Constants from a library require the library prefix.\n  assert(testlib::MAX_SIZE == 100, \"library constant MAX_SIZE\");\n  assert(testlib::MIN_SIZE == 1, \"library constant MIN_SIZE\");\n  // Library enum variants: comparison and ordering work as normal.\n  s = testlib::Ok;\n  assert(s == testlib::Ok, \"enum equality\");\n  assert(s < testlib::Error, \"enum ordering\");\n  assert(\"{s}\" == \"Ok\", \"enum to text: {s}\");\n  assert(\"Warning\" as testlib::Status == testlib::Warning, \"text to enum\");\n  // Library enum values can be passed to library free functions.\n  assert(testlib::status_text(testlib::Error) == \"err\", \"free fn with enum arg\");\n  // Structs are constructed with namespace prefix and accessed by field.\n  p = testlib::Point {x: 3.0, y: 4.0 };\n  assert(p.x == 3.0, \"field access: x={p.x}\");\n  assert(p.y == 4.0, \"field access: y={p.y}\");\n  // Methods defined in the library are called without a prefix.\n  dist = p.distance();\n  assert(round(dist) == 5.0, \"method call: distance={dist}\");\n  // User-defined method on a library type (self: testlib::Point) works.\n  assert(p.shifted(1.0, 2.0).x == 4.0, \"shifted x\");\n  assert(p.shifted(0.0, 2.0).y == 6.0, \"shifted y\");\n  // Scalar fields can be mutated directly.\n  b = testlib::Bag {label: \"test\", count: 0 };\n  b.label = \"updated\";\n  assert(b.label == \"updated\", \"direct scalar field mutation\");\n  // Methods that mutate scalar fields work.\n  b.bump();\n  assert(b.count == 1, \"method scalar mutation: count={b.count}\");\n  b.bump();\n  assert(b.count == 2, \"method scalar mutation: count={b.count}\");\n  // Free functions: called with the library prefix.\n  assert(testlib::add(3, 4) == 7, \"free function add\");\n  assert(testlib::add(0, -5) == -5, \"free function negative\");\n  // Library types work as function parameter types when written with their\n  // full namespace prefix in the function signature.\n  // A struct with a vector field can be initialised via a struct literal,\n  // including elements that are themselves library structs.\n  bag2 = testlib::Bag {label: \"full\", count: 3, items: [\n  testlib::Point {x: 1.0, y: 0.0 },\n  testlib::Point {x: 0.0, y: 1.0 }\n  ] };\n  assert(len(bag2.items) == 2, \"initialized vector field: {len(bag2.items)}\");\n  assert(bag2.items[0].x == 1.0, \"vector field element access\");\n  // Appending a struct variable with `+= [var]` and a whole vector with `+= vec` both work.\n  extra = testlib::Point {x: 7.0, y: 8.0 };\n  bag2.items +=[extra];\n  assert(len(bag2.items) == 3, \"append via var: len={len(bag2.items)}\");\n  assert(bag2.items[2].x == 7.0, \"append via var: x={bag2.items[2].x}\");\n  more_pts =[testlib::Point {x: 9.0, y: 10.0 }, testlib::Point {x: 11.0, y: 12.0 }];\n  bag2.items += more_pts;\n  assert(len(bag2.items) == 5, \"append vector: len={len(bag2.items)}\");\n  assert(bag2.items[3].x == 9.0, \"append vector[3].x={bag2.items[3].x}\");\n  // Importing the same library twice is silently ignored. A library can\n  // itself import other libraries using `use`, so dependency chains work.\n  // ## Package Layout and loft.toml\n  //\n  // A library can be distributed as a directory package instead of a single\n  // flat file. The packaged directory layout is:\n  //\n  //   mylib/\n  //     loft.toml           optional manifest\n  //     src/\n  //       mylib.loft        library source (default entry)\n  //\n  // When the interpreter searches a lib directory and finds `<dir>/mylib/`\n  // it looks for `<dir>/mylib/src/mylib.loft` automatically.\n  //\n  // The optional `loft.toml` manifest supports two settings:\n  //\n  //   [package]\n  //   loft = \">=1.0\"        minimum interpreter version required\n  //\n  //   [library]\n  //   entry = \"src/mylib.loft\"   override the default entry path\n  //\n  // If the interpreter version is below the stated minimum, loading the\n  // library produces a fatal compile error describing the version mismatch.\n  // If no manifest is present, the default entry `src/<name>.loft` is used.\n  // ## Wildcard and Selective Imports\n  // By default, library names require the `libname::` prefix. You can\n  // import names directly into your namespace with `use lib::*` (wildcard)\n  // or `use lib::Name, Other` (selective). Only `pub`-marked definitions\n  // in the library are imported this way. Non-pub definitions remain\n  // accessible via the `lib::name` prefix.\n  // ## Limitations\n  //\n  // **`use` must appear before all definitions.** If you write a function\n  // first and then a `use`, the compiler reports a syntax error.\n  //\n  // **`pub` controls import visibility.** Only `pub`-marked definitions\n  // are available via wildcard (`use lib::*`) or selective import.\n  // Non-pub definitions are still accessible with the `lib::name` prefix.\n  //\n  // **Native extensions.** A library can be pure `.loft`, or ship a Rust crate\n  // beside it: declare `native = \"...\"` in `loft.toml` and loft builds and links\n  // it for you. See PACKAGES.md for the build + binding model.\n}",
"store_locks": "// Loft gives you two separate ways to protect a value from accidental changes:\n//\n// 1. **Compile-time const**: mark a variable or parameter with 'const' and the\n//    compiler refuses to compile any code that tries to reassign it. The check\n//    happens before the program even runs — zero runtime cost.\n//\n// 2. **Runtime lock**: the '#lock' attribute on a reference lets you lock a\n//    store at runtime so that any write attempt panics immediately, even across\n//    function boundaries. This is useful for debugging: turn it on when you\n//    suspect an unexpected mutation.\nstruct Counter {\n  value: integer\n}\n// ## const parameters\n// 'const' on a parameter is a compile-time promise: \"this function will not\n// modify this value.\" The compiler enforces it — any assignment to a const\n// parameter is a compile error, caught before you run anything.\n\nfn read_value(self: const Counter) -> integer {\n  self.value\n}\n// A non-const parameter leaves the store unlocked so the function can write.\n\nfn increment(self: Counter) {\n  self.value += 1\n}\n\nfn main() {\n  // ## const local variables\n  // Declare a local variable with 'const' to signal that it will not change\n  // after its first assignment. The compiler rejects any later assignment to\n  // it — reassigning or appending to a const variable is a compile error.\n  //\n  // This is handy for configuration values or lookup tables that should never\n  // be overwritten by accident deep inside a long function.\n  const limit = 100;\n  assert(limit == 100, \"const integer is readable\");\n  // const also works for struct references.\n  const cfg = Counter {value: 42 };\n  assert(cfg.value == 42, \"const reference is readable\");\n  // Passing a const reference to a const parameter is always allowed.\n  assert(read_value(cfg) == 42, \"const passed to const param\");\n  // ## Calling methods on const references\n  // A non-const method can still be called on a non-const variable even\n  // after you have manually locked the store; the lock is a runtime check.\n  c = Counter {value: 10 };\n  increment(c);\n  assert(c.value == 11, \"increment modified c\");\n  // ## Runtime store locks with #lock\n  // '#lock' is an attribute on any reference variable.\n  // Setting it to true turns on a runtime guard: any write to that store\n  // will panic immediately, wherever it happens.\n  // A freshly created reference starts unlocked.\n  d = Counter {value: 5 };\n  assert(!d#lock, \"new store starts unlocked\");\n  d#lock = true;\n  assert(d#lock, \"store is locked after assignment\");\n  // You can still read from a locked store — only writes are blocked.\n  assert(read_value(d) == 5, \"locked store is still readable\");\n  // ## When to use each approach\n  // * Use 'const' on parameters and locals to express your design intent\n  //   and get compile-time safety at zero cost.\n  // * Use '#lock = true' when you want a runtime tripwire: you suspect some\n  //   code path is mutating a value it should not touch, and you want the\n  //   program to panic with a precise location rather than corrupt silently.\n  // get_store_lock() is the function form of the #lock attribute.\n  // Both return the same boolean.\n  e = Counter {value: 99 };\n  assert(get_store_lock(e) == e#lock, \"function form matches attribute before lock\");\n  e#lock = true;\n  assert(get_store_lock(e) == e#lock, \"function form matches attribute after lock\");\n}",
"parallel_execution": "// The `par(b=worker_call, threads)` clause on a `for` loop runs a function\n// on every element of a vector in parallel and gives you the results one by\n// one in the loop body.\n//\n// ## Why parallel loops?\n// When you have a large collection and each element can be processed\n// independently — image filters, score calculations, data transforms —\n// `par()` splits the work across CPU cores automatically.  You write a\n// normal for loop; adding `par(...)` makes it parallel with no other changes.\n//\n// ## Syntax\n//   `for a in vec par(b=func(a), N) { body }`\n//\n// - `a` — loop variable, read-only reference to the current element\n// - `b` — result variable, holds the return value of `func(a)`\n// - `func(a)` — worker function called on each element\n// - `N` — number of threads (1 = sequential, 4 = typical)\n//\n// ## Two call forms\n// - **Form 1** — global function: `par(b=my_func(a), 4)`\n// - **Form 2** — method on element: `par(b=a.my_method(), 4)`\n//\n// ## Worker function rules\n// The worker function:\n// - Takes a `const` reference to the element (read-only, no mutation)\n// - Returns a value (integer, float, boolean, text, or a struct)\n// - Must not use global state or I/O (no println, no file access)\n// - Can accept extra arguments forwarded from the calling scope\n//\n// Results are delivered in the original order regardless of which\n// thread finishes first.\nstruct Score {\n  value: integer\n}\n\nstruct ScoreList {\n  items: vector < Score >\n}\n\nstruct DoubledScore {\n  label: text,\n  doubled: integer\n}\n\nfn double_score(thr_r: const Score) -> integer {\n  thr_r.value * 2\n}\n\nfn scale_score(thr_r: const Score, thr_factor: integer) -> integer {\n  thr_r.value * thr_factor\n}\n\nfn make_doubled(thr_r: const Score) -> DoubledScore {\n  DoubledScore { label: \"v{thr_r.value}\", doubled: thr_r.value * 2 }\n}\n\nfn get_value(self: const Score) -> integer {\n  self.value\n}\n\nfn make_scores() -> ScoreList {\n  thr_q = ScoreList { };\n  thr_q.items +=[Score {value: 10 }, Score {value: 20 }, Score {value: 30 }];\n  thr_q\n}\n\n// come back in order, whatever the thread count\nfn main() {\n  // ## Global Function (Form 1)\n  // Each Score's value is doubled by `double_score` across 4 threads.\n  // The loop body sees `b` with the doubled value, in original order.\n  q = make_scores();\n  sum = 0;\n  for thr_a in q.items par(thr_b = double_score(thr_a), 4) {\n    sum += thr_b;\n  }\n  // 10*2 + 20*2 + 30*2 = 120\n  assert(sum == 120, \"parallel double: sum == 120\");\n\n  // ## Extra Arguments\n  // The worker function can take extra arguments from the calling scope.\n  // Here `scale_score(a, factor)` passes `factor=3` to every worker.\n  q1b = make_scores();\n  factor = 3;\n  scaled_sum = 0;\n  for thr_a in q1b.items par(thr_b = scale_score(thr_a, factor), 4) {\n    scaled_sum += thr_b;\n  }\n  // 10*3 + 20*3 + 30*3 = 180\n  assert(scaled_sum == 180, \"extra arg: scaled sum == 180\");\n\n  // ## Struct Return\n  // Workers can return a struct.  Text fields are deep-copied so they\n  // remain valid after the worker thread exits.\n  q2 = make_scores();\n  labels = \"\";\n  for thr_sa in q2.items par(thr_ds = make_doubled(thr_sa), 1) {\n    labels += \"{thr_ds.label},\";\n  }\n  assert(labels == \"v10,v20,v30,\", \"struct return: {labels}\");\n\n  // ## Method Call (Form 2)\n  // `b=a.get_value()` dispatches the method on each element in parallel.\n  // This is syntactic sugar — equivalent to `b=get_value(a)`.\n  q3 = make_scores();\n  total = 0;\n  for thr_a in q3.items par(thr_b = thr_a.get_value(), 4) {\n    total += thr_b;\n  }\n  assert(total == 60, \"method call: total == 60\");\n\n  // ## Empty Vector\n  // An empty vector is safe — the loop body never executes,\n  // no threads are spawned.\n  empty = ScoreList { };\n  thr_n = 0;\n  for thr_a in empty.items par(thr_b = double_score(thr_a), 1) {\n    thr_n += 1;\n  }\n  assert(thr_n == 0, \"empty: 0 iterations\");\n\n  // ## Sequential fallback\n  // Using `par(..., 1)` runs the worker on a single thread — useful\n  // for debugging.  The behaviour is identical; only the parallelism changes.\n  q4 = make_scores();\n  seq_sum = 0;\n  for thr_a in q4.items par(thr_b = double_score(thr_a), 1) {\n    seq_sum += thr_b;\n  }\n  assert(seq_sum == 120, \"sequential par(1): same result\");\n}",
"logging": "// Printing everything to the console is fine during development, but in a\n// real application you usually want more control: write to a file, filter\n// by severity, and keep the output even after the terminal session ends.\n// Loft's logging functions give you that without changing your source code.\n// ## The four severity levels\n//\n// Choose the level that matches how serious the event is:\n//\n// * 'log_info'  — routine progress; fine to see during development but often\n//   silenced in production to keep log files small.\n//   Example: \"processing file X\", \"connected to database\".\n//\n// * 'log_warn'  — something unexpected happened but the program recovered.\n//   Example: \"config key missing, using default\", \"retrying after timeout\".\n//\n// * 'log_error' — something went wrong and you need to investigate, but the\n//   program can continue (perhaps degraded).\n//   Example: \"failed to save record\", \"unexpected null value\".\n//\n// * 'log_fatal' — a condition so serious that normal operation is impossible.\n//   Example: \"cannot open database\", \"required config file not found\".\n// ## Configuring the log destination\n//\n// By default, log calls do nothing — no file is written, no console output\n// is produced. To switch logging on, place a 'log.conf' file in the\n// same directory as your '.loft' file, or pass '--log-conf path/to/log.conf'\n// on the command line.\n//\n// Generate a documented template with all defaults by running:\n//   loft --generate-log-config\n//\n// A minimal 'log.conf' looks like this:\n//\n//   [log]\n//   file  = log.txt    # write messages here (relative to the .loft file)\n//   level = info       # minimum level to record; choices: info warn error fatal\n//\n//   [rotation]\n//   max_size_mb = 500  # start a new log file after this many megabytes\n//   daily       = true # also start a new file at midnight UTC\n//   max_files   = 10   # keep at most this many log files (older ones are deleted)\n//\n//   [rate_limit]\n//   per_site = 5       # suppress messages from the same source line after 5/minute\n//\n//   [levels]\n//   # Override the global level for a specific file:\n//   # \"debug_tool.loft\" = info\n//   # \"src/\"            = error\n// ## Production mode\n//\n// When 'production = true' is set in log.conf:\n// * 'panic()' becomes a fatal log entry instead of aborting the process.\n// * A failing 'assert()' becomes an error log entry instead of aborting.\n// The program keeps running and the problem is captured in the log — useful\n// for long-running services where a single error should not bring everything down.\n// ## Using format strings in log messages\n//\n// Log messages are plain text, but you can embed any expression using the\n// same '{...}' format syntax as everywhere else in Loft. The interpolation\n// happens only when the message is actually going to be written; if the\n// configured level is higher than the call, the string is never evaluated\n// (no performance cost for suppressed messages).\nfn main() {\n  // Without a log.conf these calls do nothing — the tests below pass\n  // even though no output is produced.\n  log_info(\"starting up\");\n  log_warn(\"this is a warning\");\n  log_error(\"something went wrong\");\n  log_fatal(\"critical failure\");\n  // ## Example log.txt output\n  //\n  // When a 'log.conf' is present with 'level = info', the four calls above\n  // produce entries like this in 'log.txt':\n  //\n  //   2026-03-24 09:15:00 INFO   app.loft:3  starting up\n  //   2026-03-24 09:15:00 WARN   app.loft:4  this is a warning\n  //   2026-03-24 09:15:00 ERROR  app.loft:5  something went wrong\n  //   2026-03-24 09:15:00 FATAL  app.loft:6  critical failure\n  //\n  // Each line contains: timestamp, severity level, source file and line\n  // number, then the message. This makes it easy to search the file for\n  // errors or trace back to the exact line that produced a message.\n  // A true assert never logs anything — it is only the false case that logs.\n  assert(true, \"this should never fail\");\n  // ## Typical usage pattern\n  //\n  // In a real program you would write something like:\n  //\n  //   fn process(item: Item) {\n  //       log_info(\"processing item {item.id}\");\n  //       result = do_work(item);\n  //       if !result {\n  //           log_error(\"work failed for item {item.id}\");\n  //           return;\n  //       }\n  //       log_info(\"finished item {item.id} successfully\");\n  //   }\n  //\n  // The log messages give you a record of exactly what the program did and\n  // where it went wrong, without cluttering the terminal during normal runs.\n  println(\"logging test passed\");\n}",
"time": "// Loft provides two time functions:\n//\n//   now()     — milliseconds since the Unix epoch (wall-clock time).\n//   ticks()   — microseconds elapsed since program start (monotonic clock).\n//\n// Both return an 'integer' (loft's 64-bit integer).\n//\n// Use 'now()' for timestamps, log entries, and date calculations.\n// Use 'ticks()' for benchmarks and frame timing — it is unaffected by\n// system clock changes or NTP adjustments.\nfn main() {\n  // ## Wall-clock time: now()\n  // 'now()' returns the current time as milliseconds since 1970-01-01T00:00:00 UTC.\n  // The value is always positive and grows over time.\n  t = now();\n  assert(t > 0, \"now() must be positive\");\n  // Two successive calls return non-decreasing values.\n  t2 = now();\n  assert(t2 >= t, \"now() must be non-decreasing\");\n  // ## Elapsed time: ticks()\n  // 'ticks()' measures microseconds since the program started.\n  // It uses a monotonic clock so it never jumps backward.\n  start = ticks();\n  assert(start >= 0, \"ticks() must be non-negative\");\n  end = ticks();\n  assert(end >= start, \"ticks() must be monotonically non-decreasing\");\n  // ## Measuring elapsed time\n  // Subtract two 'ticks()' values to get the duration in microseconds.\n  // Divide by 1000 to convert to milliseconds.\n  //\n  //   elapsed_us  = end_ticks - start_ticks\n  //   elapsed_ms  = elapsed_us / 1000\n  //\n  // Example: measure how long a loop takes.\n  t_before = ticks();\n  sum = 0;\n  for i in 0..1000 {\n    sum += i\n  }\n  t_after = ticks();\n  elapsed = t_after - t_before;\n  assert(elapsed >= 0, \"elapsed time must be non-negative: {elapsed}\");\n  assert(sum == 499500, \"loop produced wrong sum: {sum}\");\n  // ## Common patterns\n  //\n  // Timestamp a log entry (seconds since epoch):\n  //   seconds = now() / 1000\n  //\n  // Seed the random number generator with the current time\n  // (now() already returns an integer, so no cast is needed):\n  //   rand_seed(now())\n  //\n  // Simple stopwatch:\n  //   start = ticks()\n  //   ... do work ...\n  //   log_info(\"Done in {(ticks() - start) / 1000} ms\")\n}",
"safety": "// Loft catches many errors at compile time, but a few surprises remain at\n// runtime. This page catalogues every known trap so you can write confident\n// code from day one. Each section includes a live example that proves the\n// described behavior.\n// Helper used in the '??' double-evaluation example below.\n// Increments the call counter and returns the given value unchanged.\nfn counted_call(calls: &integer, value: integer) -> integer {\n  calls += 1;\n  value\n}\n\n// Used to obtain a null text value (an uninitialized field is the NUL sentinel).\nstruct NullTextHolder {\n  s: text,\n}\n\nstruct OptTextHolder {\n  s: text?,\n}\n\nfn main() {\n  // ## Null values — hidden reserved values\n  // Every type reserves one special value to mean \"nothing here\" (null).\n  // That reserved value looks like any other value, so be aware of what it\n  // is for each type:\n  // - `boolean`         — `false` is the null value\n  // - `integer`         — the most negative 64-bit integer (-9 223 372 036 854 775 808) is null\n  // - `float`/`single`  — `NaN` (Not a Number) is null\n  // - `character`       — the NUL character (code point 0) is null\n  // - `text`            — a single NUL character (`'\\0'`) is null; the empty string `\"\"` is NOT null\n  // - `reference`       — record 0 is null\n  // - plain `enum`      — byte value 255 is null (limits enums to 255 variants)\n  //\n  // This means there is one value per type that you cannot distinguish from\n  // null. For integers, that is -9 223 372 036 854 775 808.  When defended\n  // with `?? null` (or a following null-check), division by zero produces\n  // this same value, so both paths look the same to your code:\n  zero = 0;\n  n = 1 / zero ?? null;\n  assert(!n, \"div-by-zero defended with `?? null` is null\");\n  assert(n != 0, \"null is not zero; it is -9 223 372 036 854 775 808\");\n  assert(n < 0, \"i64::MIN is the most negative 64-bit integer\");\n  // Arithmetic on null propagates: null plus anything is null.\n  assert(! (n + 1), \"null + 1 is still null\");\n  // Text null is the NUL character ('\\0'), not the empty string. A `text?` local\n  // or field can hold it; a plain `text` cannot, and a parse respects that.\n  holder = NullTextHolder.parse(`{{}}`);\n  assert(holder.s == \"\", \"a missing `text` field is empty, because it cannot be null\");\n  opt = OptTextHolder.parse(`{{}}`);\n  assert(!opt.s, \"a missing `text?` field IS null — the declaration decides\");\n  empty = \"\";\n  assert(empty, \"empty string is NOT null — this surprises most newcomers\");\n\n  // ## Parsing text to a number needs a fallback\n  // An unchecked `text as integer` is a COMPILE error: parsing can fail, and\n  // loft refuses to let that failure slip through as a silent null. Ask for a\n  // checked cast with `integer?` (yields the number or null), or supply a\n  // default with `?? <value>`. The same rule applies to `float`.\n  parsed = \"42\" as integer?;\n  assert(parsed == 42, \"checked cast `as integer?` yields the number\");\n  fallback = \"oops\" as integer? ?? -1;\n  assert(fallback == -1, \"unparseable text falls back to the default\");\n\n  // ## Integer overflow yields null\n  // A calculation that overflows the integer range is uncomputable, so loft\n  // yields null and keeps running — it never wraps to a silently-wrong number\n  // (the way C, or a Rust release build, would) and it never crashes. One bad\n  // value degrades locally; the rest of the program still computes.\n  //   huge = 9223372036854775807; huge + 1  →  null (not a wrapped negative)\n  // To trace where overflows arise, opt into the debug log level. Mitigation:\n  // check the result for null, or keep intermediate values within range.\n  huge = 9223372036854775807;\n  assert(! (huge + 1), \"overflow yields null, not a wrapped value\");\n\n  // ## Bitwise operators with zero\n  // All bitwise operators (AND, OR, XOR, shift) work correctly with zero.\n  // Zero is the identity element for OR, XOR, and shift; zero for AND.\n  assert(0b1010&0 == 0, \"AND with 0: zero\");\n  assert(0b1010|0 == 0b1010, \"OR with 0: identity\");\n  assert(0b1010^0 == 0b1010, \"XOR with 0: identity\");\n  assert(5<<0 == 5, \"shift left by 0: identity\");\n  assert(5>>0 == 5, \"shift right by 0: identity\");\n\n  // ## Float null compares uniformly with every other scalar\n  // Floats store null as `NaN` internally, but null COMPARISON is uniform with\n  // every other scalar type (@PLN102 null model): `null == null` is TRUE, null is\n  // not equal to any real value, and null orders as the low extreme. Detect a\n  // null float with `f == null` (or `!f` / `f ?? default`) — NOT the old `f != f`\n  // trick, which no longer works now that `null == null` is true.\n  // Both the defended and the undefended division yield null and continue\n  // (C80 / E-Uncomp — see tests/scripts/184-i333-div-zero-null-continues.loft);\n  // the undefended site additionally reports a warning.\n  bad = 0.0 / 0.0 ?? null;\n  assert(!bad, \"a null float is falsy\");\n  assert(bad == null, \"detect a null float with `== null`\");\n  assert(bad == bad, \"null == null is true (uniform null model)\");\n  assert(! (bad != null), \"a null float `!= null` is false\");\n  assert(bad != 0.0, \"null != 0.0 is true\");\n  // Use `f == null`, `!f`, or `f ?? default` to check for null floats.\n\n  // ## Text length counts characters; size counts bytes\n  // `len()` on text returns the number of characters (Unicode code points) — the\n  // human count. `size()` returns the number of UTF-8 bytes; multi-byte characters\n  // (accented letters, emoji, CJK) each occupy 2-4 bytes. The two values differ\n  // whenever the text contains any multi-byte character.\n  emoji = \"Hi 😊!\";\n  assert(len(emoji) == 5, \"5 characters (H, i, space, 😊, !)\");\n  assert(size(emoji) == 8, \"8 UTF-8 bytes (the emoji is 4): {size(emoji)}\");\n  // Slicing and indexing also use byte offsets. Slicing in the middle of a\n  // multi-byte character is an error.\n  // Mitigation: Use `for c in text` to iterate by character. Use\n  // `c#index` and `c#next` to get the byte boundaries of each character.\n  count = 0;\n  for c in emoji { count += 1; }\n  assert(count == 5, \"for-loop iterates by character, not byte\");\n\n  // ## `#index` means different things on text and vectors\n  // On a text loop, `c#index` is the byte offset of the current character.\n  // On a vector loop, `v#index` is the 0-based element position.\n  // Both are called `#index` but represent different units.\n  v = [10, 20, 30];\n  idx = 0;\n  for x in v { idx = x#index; }\n  assert(idx == 2, \"vector #index: element position (0-based)\");\n  // Text #index is a byte offset, not a character count:\n  t = \"aé\";\n  byte_pos = 0;\n  for c in t { byte_pos = c#index; }\n  assert(byte_pos == 1, \"text #index: byte offset of 'é' (byte 1, not char 1)\");\n\n  // ## `??` evaluates the left side exactly once\n  // The `??` operator means \"use this value, or if it is null, use the right side instead\".\n  // The left-hand expression is evaluated exactly once regardless of whether the result is\n  // null. The example below uses `counted_call` (defined above) to verify this.\n  calls = 0;\n  qq_result = counted_call(calls, 7) ?? 99;\n  assert(calls == 1, \"?? evaluated left side exactly once: {calls}\");\n  assert(qq_result == 7, \"result is the value from that single evaluation: {qq_result}\");\n  // This means `result = expensive_call() ?? default` is safe: the function\n  // is called once. If it returns null, `default` is used. There is no double call.\n\n  // ## Text indexing and slicing return different types\n  // `txt[i]` returns a `character` (a single Unicode scalar value).\n  // `txt[i..j]` returns `text` (a UTF-8 string). These are different types.\n  txt = \"hello\";\n  ch = txt[0];\n  slice = txt[0..1];\n  assert(ch == 'h', \"indexing returns a character\");\n  assert(slice == \"h\", \"slicing returns text\");\n  // Building text from characters requires format interpolation:\n  result = \"\";\n  for c in \"abc\" { result += \"{c}\"; }\n  assert(result == \"abc\", \"characters must be formatted into text\");\n\n  // ## Format strings: braces are always interpreted\n  // Every string literal in loft is a format string. Literal braces must\n  // be escaped as `{{` and `}}`:\n  n = 42;\n  assert(\"{n}\" == \"42\", \"single braces: format expression\");\n  assert(len(\"{{}}\") == 2, \"double braces produce literal brace chars\");\n  // Forgetting to escape braces in expected output is a common mistake in\n  // assertions and comparisons.\n\n  // ## Hash collections cannot be iterated\n  // Hashes are lookup structures, not ordered collections. You cannot write\n  // `for item in my_hash { }`. If you need both fast lookup and ordered\n  // iteration, keep a vector and a hash pointing at the same record type.\n  // See the Hash documentation page for the recommended pattern.\n\n  // ## Mutation guard blocks appending during iteration\n  // The compiler prevents `v += [x]` inside `for e in v`. This protects\n  // against infinite loops. The guard also catches field access:\n  // `for e in db.items { db.items += [x]; }` is blocked too.\n  // The only allowed mutation is `e#remove` inside a filtered loop.\n\n  // ## If-expression requires else when used as a value\n  // Using `if` as a value expression without an `else` clause is a compile\n  // error. This prevents accidental null values from missing branches.\n  // If-statements (where the body has no value) do not need else.\n  // For example, `x = if cond { 1 }` is an error; write `x = if cond { 1 } else { 0 }`.\n\n  // ## Match guards do not prove a variant is handled\n  // A guarded arm like `Red if cond => ...` does not count as handling\n  // the `Red` variant because the guard can fail at runtime. Even if\n  // every variant has a guarded arm, you still need a wildcard `_` or an\n  // unguarded arm so the compiler knows every case is covered.\n\n  // ## Ref-parameter semantics\n  // Without `&`, appending to a vector parameter is local — the caller's\n  // vector does not grow. With `&`, the caller sees the new elements.\n  // Field-level mutations (e.g. `v[i].field = x`) are always visible to the\n  // caller because both sides share the same underlying database reference.\n  // Rule of thumb: Use `&vector<T>` when the function needs to grow the\n  // vector. Use plain `vector<T>` when the function only reads or modifies\n  // existing elements.\n\n  // ## Text file reading assumes UTF-8\n  // `lines()` and `content()` read a file as UTF-8 text and crash on invalid\n  // UTF-8 (a binary file, or a different encoding such as Latin-1). For binary\n  // data, set a binary format on the file — `f#format = LittleEndian` (or\n  // `BigEndian`) — and read raw bytes / integers directly (see 13-file.loft).\n  // So: read UTF-8 text in text mode, everything else in a binary format.\n\n  // ## XOR is `^`, not exponentiation\n  // Unlike some languages where `^` means \"power\", in loft `^` is bitwise\n  // XOR. For exponentiation use the `**` operator (`2 ** 10 == 1024`,\n  // `2.0 ** 3.0 == 8.0`) or the `pow()` function. Watch one precedence footgun:\n  // `-x ** y` parses as `-(x ** y)`, so loft warns on it — write `(-x) ** y`\n  // when you mean to raise a negated base.\n  assert((0b1010^0b1100) == 0b0110, \"^ is XOR\");\n  assert(2**10 == 1024, \"** is the power operator\");\n  assert(pow(2.0, 3.0) == 8.0, \"pow() also computes powers\");\n}",
"json": "// Loft has built-in JSON support: any struct can be serialised to JSON with a\n// format flag, and parsed back from JSON text.  No annotations or code generation\n// needed — it works on every struct automatically.\n//\n// ## Serialisation — struct to JSON\n// Use the ':j' format flag inside a format string to produce JSON output.\n// Field names become quoted keys; strings are escaped; numbers and booleans\n// are written as JSON literals.\n//\n//   \"{my_struct:j}\"\n//\nstruct User {\n  id: integer,\n  name: text,\n  email: text\n}\n\nstruct MaybeUser {\n  id: integer,\n  name: text?,\n}\n\n// ## Parsing — JSON to struct\n// Call 'Type.parse(text)' to create a struct from JSON text.\n// Text arguments are auto-wrapped through 'json_parse' internally.\n//\n// A field the JSON does not mention — and a field written 'null' — gets the\n// DECLARED type's absent value.  For a plain field that is its zero, because a\n// plain field cannot hold null; write the field 'integer?' / 'float?' if you\n// need to tell \"absent\" from \"zero\" apart:\n//\n//   struct Reading { id: integer, drift: float? }\n//   r = Reading.parse(\"{}\")     // r.id == 0, r.drift == null\n//\n// Caveat (Q1): the auto-wrap form DROPS diagnostics — malformed input and\n// schema mismatches leave the struct at its defaults with 'json_errors()'\n// empty.  For error reporting, stage explicitly:\n// 'User.parse(json_parse(text))' — that form pushes both parse and schema\n// errors to 'json_errors()'.\n//\n//   user = User.parse(json_text)\n// to inspect 'json_errors()' between the two steps.\n//\n// ## Vectors\n// Parse a JSON array into a vector of structs with 'vector<T>.parse(text)'.\n//\n//   scores = vector<Score>.parse(\"[{\\\"v\\\":1},{\\\"v\\\":2}]\")\n//\nstruct Score {\n  value: integer\n}\n\n// ## Parse Errors\n// Call 'json_errors()' to see what went wrong with a malformed\n// input.  Schema-level mismatches (e.g. a field declared integer\n// but receiving a JSON string) currently land as the loft null\n// sentinel in the struct; Q1 schema-side diagnostics will add\n// path-qualified reports in a follow-up.\n//\n//   data = MyType.parse(bad_json);\n//   if len(json_errors()) > 0 { log_warn(json_errors()); }\n//\n// ## Nested Structs\n// Structs with struct-typed fields parse nested JSON objects automatically.\n//\nstruct Address {\n  city: text,\n  zip: text\n}\n\nstruct Contact {\n  name: text,\n  address: Address\n}\n\nfn main() {\n  u = User { id: 42, name: \"Alice\", email: \"alice@example.com\" };\n  json = \"{u:j}\";\n  expected = `{{\"id\":42,\"name\":\"Alice\",\"email\":\"alice@example.com\"}}`;\n  assert(json == expected, \"to json\");\n\n  bob = User.parse(`{{\"id\":7,\"name\":\"Bob\",\"email\":\"bob@test.org\"}}`);\n  assert(bob.id == 7, \"parsed id: {bob.id}\");\n  assert(bob.name == \"Bob\", \"parsed name\");\n  assert(bob.email == \"bob@test.org\", \"parsed email\");\n\n  u2 = User.parse(\"{u:j}\");\n  assert(u2.id == u.id, \"round-trip id\");\n  assert(u2.name == u.name, \"round-trip name\");\n\n  // Type-mismatched fields (id: string, name: number) parse as JSON fine, but the\n  // struct unwrap abandons the record at its defaults; path-qualified diagnostics\n  // on the mismatch are collected in `json_errors`. `id` is declared plain, so its\n  // default is 0 — the mismatch is reported through `json_errors`, never by putting\n  // a null in a slot the declared type says cannot hold one. Here we verify the\n  // unwrap does not crash on mismatched shapes.\n  bad = User.parse(`{{\"id\":\"not_a_number\",\"name\":42}}`);\n  assert(bad.id == 0, \"type-mismatched id keeps its default: {bad.id}\");\n\n  scores = vector<Score>.parse(`[{{\"value\":10}},{{\"value\":20}},{{\"value\":30}}]`);\n  total = 0;\n  for s in scores {\n    total += s.value;\n  }\n  assert(total == 60, \"vector sum: {total}\");\n\n  c = Contact.parse(`{{\"name\":\"Carol\",\"address\":{{\"city\":\"Amsterdam\",\"zip\":\"1012\"}}}}`);\n  assert(c.name == \"Carol\", \"nested name\");\n  assert(c.address.city == \"Amsterdam\", \"nested city: {c.address.city}\");\n  assert(c.address.zip == \"1012\", \"nested zip\");\n\n  // ## A missing field gets its own declared absence\n  // When a field is absent from the JSON, it gets the absent value its DECLARATION\n  // allows — not the type's null sentinel. A plain field cannot hold null, so it\n  // takes its empty value: 0 for a number, \"\" for text, false for a boolean. Declare\n  // the field 'T?' when \"the document did not say\" has to be tellable from \"the\n  // document said zero\", and check it with '!' or '??' before use.\n  partial = User.parse(`{{\"id\":1}}`);\n  assert(partial.id == 1, \"partial id\");\n  assert(partial.name == \"\", \"a missing `text` field is empty: [{partial.name}]\");\n  maybe = MaybeUser.parse(`{{\"id\":1}}`);\n  assert(!maybe.name, \"a missing `text?` field is null\");\n}",
"generics": "// A generic function uses a type variable to work with any type.\n// Write the function once; the compiler creates a specialised copy for each\n// concrete type you call it with.\n// ## Declaring a generic function\n// Place a single type variable in angle brackets after the function name.\n// The type variable must appear in the first parameter (directly or as a\n// container element like vector<T>).\nfn identity<T>(x: T) -> T { x }\n// ## Calling a generic function\n// No special syntax at the call site — the compiler infers T from the first\n// argument's type and creates a specialised copy automatically.\nfn test_identity() {\n  assert(identity(42) == 42, \"identity integer\");\n  assert(identity(3.14) == 3.14, \"identity float\");\n  assert(identity(\"hello\") == \"hello\", \"identity text\");\n  assert(identity(true) == true, \"identity bool\");\n}\n// ## Multiple parameters of the same type\n// Additional parameters can also use T.  They all share the same concrete type.\nfn pick_second<T>(gen_a: T, gen_b: T) -> T {\n  _x = gen_a;\n  gen_b\n}\nfn test_pick_second() {\n  assert(pick_second(1, 99) == 99, \"pick second int\");\n  assert(pick_second(\"a\", \"b\") == \"b\", \"pick second text\");\n}\n// ## Generic functions on vectors\n// The most common use of generics: write a function that works on any vector.\n// T is inferred from the vector's element type.\nfn first_element<T>(gen_v: vector<T>) -> T {\n  gen_v[0]\n}\n// read is nullable; a generic has no `?? default`, so the honest result type is `T?`.\nfn last_element<T>(gen_v: vector<T>) -> T? {\n  gen_v[gen_v.len() - 1]\n}\nfn test_vector_generics() {\n  ints = [10, 20, 30];\n  assert(first_element(ints) == 10, \"first int\");\n  assert(last_element(ints) == 30, \"last int\");\n  words = [\"alpha\", \"beta\", \"gamma\"];\n  assert(first_element(words) == \"alpha\", \"first text\");\n  assert(last_element(words) == \"gamma\", \"last text\");\n}\n// ## Bounded generics with interfaces\n// By default, you can only assign and return T — no arithmetic, no comparison.\n// To use operators on T, add an interface bound: `<T: Ordered>` means T must\n// support `<`, `<=`, `>`, `>=` comparisons.\n//\n// Built-in interfaces:\n//   Ordered    — comparison operators (<, <=, >, >=)\n//   Equatable  — equality operators (==, !=)\n//   Addable    — addition and subtraction (+, -)\n//   Numeric    — all four scalar operators (+, -, *, /)\n//   Scalable   — multiplication by a float factor (* float)\n//   Printable  — text conversion (to_text)\nfn gen_max<T: Ordered>(gen_x: T, gen_y: T) -> T {\n  if gen_x > gen_y { gen_x } else { gen_y }\n}\nfn gen_min<T: Ordered>(gen_x: T, gen_y: T) -> T {\n  if gen_x < gen_y { gen_x } else { gen_y }\n}\nfn test_bounded() {\n  assert(gen_max(3, 7) == 7, \"max int\");\n  assert(gen_max(2.5, 1.5) == 2.5, \"max float\");\n  assert(gen_min(3, 7) == 3, \"min int\");\n  assert(gen_min(\"apple\", \"banana\") == \"apple\", \"min text\");\n}\n// ## Combining bounds\n// Use `+` to require multiple interfaces: `<T: Ordered + Addable>`.\nfn clamped_add<T: Ordered + Addable>(gen_a: T, gen_b: T, gen_hi: T) -> T {\n  result = gen_a + gen_b;\n  if result > gen_hi { gen_hi } else { result }\n}\nfn test_combined_bounds() {\n  assert(clamped_add(3, 4, 10) == 7, \"under limit\");\n  assert(clamped_add(8, 5, 10) == 10, \"clamped to limit\");\n  assert(clamped_add(1.0, 2.0, 2.5) == 2.5, \"float clamped\");\n}\n// ## Allowed operations on T\n// Inside a generic function you may only use operations that the bound\n// guarantees.  Without any bound: assign, return, store in variables.\n// With Ordered: comparisons.  With Addable: + and -.\n// ## Disallowed operations\n// The compiler rejects operations not covered by the bound.\n// `x + y` on unbounded T gives:\n//   \"generic type T: operator '+' requires a concrete type\"\n// `x.field` on T gives:\n//   \"generic type T: field access requires a concrete type\"\nfn main() {\n  test_identity();\n  test_pick_second();\n  test_vector_generics();\n  test_bounded();\n  test_combined_bounds();\n}",
"closures": "// A closure is a lambda that reads variables from the function scope in which\n// it is written.  No explicit capture list is needed — the compiler detects\n// which outer variables the lambda body uses and packages them automatically.\n// ## Integer capture\n// A lambda may read any integer variable in scope.\n// Store the lambda, then call it by name.\n// ## Multiple integer captures\n// A lambda can read more than one outer variable at once.\n// All are captured at the moment the lambda is written.\n// ## Text capture\n// Text values are captured by deep-copy, so they are independent of the\n// original variable after capture.\n// ## Capture timing\n// Loft captures variables at the moment the lambda is written (definition\n// time), not when it is called.  If a variable changes after the lambda\n// is written, the lambda still sees the original value.\n// ## Cross-scope closures\n// A function can return a capturing lambda to the caller. The captured\n// values travel with the lambda — no dangling references.\n// ## Closures with higher-order functions\n// A capturing closure stored in a variable can be called directly.\n// ## Non-capturing lambdas with higher-order functions\n// Lambdas that use only their own parameters (no capture) also work fine.\n\nfn make_adder(base_val: integer) -> fn(integer) -> integer {\n  fn(n: integer) -> integer { base_val + n }\n}\n\nfn main() {\n  // ## Integer capture\n  offset = 100;\n  shift = fn(x: integer) -> integer { x + offset };\n  assert(shift(5) == 105, \"shift(5): {shift(5)}\");\n  assert(shift(-3) == 97, \"shift(-3): {shift(-3)}\");\n\n  // ## Multiple integer captures\n  lo = 10;\n  hi = 20;\n  clamp_val = fn(x: integer) -> integer {\n    if x < lo { lo } else if x > hi { hi } else { x }\n  };\n  assert(clamp_val(5) == 10, \"clamp below: {clamp_val(5)}\");\n  assert(clamp_val(15) == 15, \"clamp mid: {clamp_val(15)}\");\n  assert(clamp_val(25) == 20, \"clamp above: {clamp_val(25)}\");\n\n  // ## Text capture\n  greeting = \"Hello\";\n  make_msg = fn(name: text) -> text { \"{greeting}, {name}!\" };\n  assert(make_msg(\"World\") == \"Hello, World!\", \"greeting capture\");\n  assert(make_msg(\"Loft\") == \"Hello, Loft!\", \"greeting capture 2\");\n\n  // ## Capture timing\n  // Closures capture at definition time. 'base' is 10 when the lambda is\n  // written; reassigning 'base' to 20 afterwards does not affect the\n  // captured value.\n  base = 10;\n  add_base = fn(n: integer) -> integer { base + n };\n  base = 20;\n  assert(add_base(5) == 15, \"sees base=10 at definition time: {add_base(5)}\");\n\n  // ## Cross-scope closures\n  // make_adder returns a lambda that captured base_val from its parameter.\n  add10 = make_adder(10);\n  add100 = make_adder(100);\n  assert(add10(5) == 15, \"add10(5): {add10(5)}\");\n  assert(add100(5) == 105, \"add100(5): {add100(5)}\");\n\n  // ## Closures with higher-order functions\n  factor = 3;\n  scale = fn(x: integer) -> integer { x * factor };\n  assert(scale(5) == 15, \"scale(5): {scale(5)}\");\n  assert(scale(10) == 30, \"scale(10): {scale(10)}\");\n\n  // ## Non-capturing lambdas with higher-order functions\n  // No capture needed here — the lambda uses only its own parameter.\n  nums = [1, 2, 3, 4, 5];\n  doubled = map(nums, |x| { x * 2 });\n  assert(doubled[0] == 2, \"doubled[0]: {doubled[0]}\");\n  assert(doubled[4] == 10, \"doubled[4]: {doubled[4]}\");\n\n  evens = filter(nums, |x| { x % 2 == 0 });\n  assert(evens[0] == 2, \"evens[0]: {evens[0]}\");\n  assert(evens[1] == 4, \"evens[1]: {evens[1]}\");\n}",
"coroutines": "// #warn Variable d is never read\n// A generator function produces values one at a time.\n// Declare the return type as 'iterator<T>' and use 'yield' to emit each value.\n// The function body is suspended between yields and resumed when the next\n// value is requested.  When the body finishes the generator is exhausted.\n// Generators are useful when you want to produce values on demand, stop early\n// with 'break', or chain sequences without building intermediate collections.\n// ## Declaring a generator function\n// A function whose return type is 'iterator<T>' is a generator.\n// 'yield value' emits one item and pauses; the next call resumes from there.\n// ## Iterating with a for loop\n// A 'for' loop drives the generator forward automatically.\n// The body runs once per yielded value.\n// Use 'break' to stop early without consuming the rest.\n// ## Manual advance with next() and exhausted()\n// Call 'next(gen)' yourself when you need fine-grained control.\n// 'exhausted(gen)' returns true once there are no more values.\n// ## Generators with parameters\n// A generator function may take any parameters, including text.\n// Parameter values are preserved across yields so the generator can\n// use them throughout its lifetime.\n// ## Delegation with yield from\n// 'yield from sub_gen()' forwards all values from another generator\n// inline, as if each of its yields appeared at this point directly.\n// ## Early termination with break\n// Stopping a 'for' loop before the generator is exhausted is safe.\n// The abandoned generator frame is freed automatically.\n\nfn count_up(start: integer, stop: integer) -> iterator<integer> {\n  for i in start..stop {\n    yield i;\n  }\n}\n\nfn squares(n: integer) -> iterator<integer> {\n  for i in 1..=n {\n    yield i * i;\n  }\n}\n\n// Yields the length of 's' twice — shows that a text parameter survives yields.\nfn len_twice(s: text) -> iterator<integer> {\n  yield len(s);\n  yield len(s);\n}\n\nfn inner_vals() -> iterator<integer> {\n  yield 10;\n  yield 20;\n}\n\nfn outer_combined() -> iterator<integer> {\n  yield 1;\n  yield from inner_vals();\n  yield 2;\n}\n\nfn large_range(limit: integer) -> iterator<integer> {\n  for i in 1..=limit {\n    yield i;\n  }\n}\n\nfn main() {\n  // ## Iterating with a for loop\n  total = 0;\n  for n in count_up(1, 6) {\n    total += n;\n  }\n  assert(total == 15, \"sum 1..5: {total}\");\n\n  // Squares via for loop with index tracking.\n  idx = 0;\n  for s in squares(4) {\n    idx += 1;\n    if idx == 1 { assert(s == 1, \"sq1: {s}\"); }\n    if idx == 2 { assert(s == 4, \"sq2: {s}\"); }\n    if idx == 3 { assert(s == 9, \"sq3: {s}\"); }\n    if idx == 4 { assert(s == 16, \"sq4: {s}\"); }\n  }\n  assert(idx == 4, \"squares count: {idx}\");\n\n  // ## Manual advance with next() and exhausted()\n  gen = count_up(10, 13);\n  a = next(gen);\n  b = next(gen);\n  c = next(gen);\n  assert(a == 10 && b == 11 && c == 12, \"manual next: {a},{b},{c}\");\n  // One extra advance past the last element; exhausted() is true after that.\n  d = next(gen);\n  done = exhausted(gen);\n  assert(done, \"exhausted after last value\");\n\n  // ## Generators with parameters\n  // 'len_twice' takes a text parameter and yields its length twice.\n  // The text value is preserved across the yield.\n  lt_total = 0;\n  for n in len_twice(\"hello\") {\n    lt_total += n;\n  }\n  assert(lt_total == 10, \"len_twice: {lt_total}\");\n\n  // ## Delegation with yield from\n  yf_total = 0;\n  for n in outer_combined() {\n    yf_total += n;\n  }\n  assert(yf_total == 33, \"yield from: 1+10+20+2={yf_total}\");\n\n  // ## Early termination with break\n  // Stop after the first 5 values from a 1000-element generator.\n  limit_total = 0;\n  for n in large_range(1000) {\n    if n > 5 { break; }\n    limit_total += n;\n  }\n  assert(limit_total == 15, \"early break sum 1..5: {limit_total}\");\n}",
"tuples": "// A tuple groups a fixed number of values of possibly different types.\n// You do not need to give a tuple a name — use it directly where you need\n// to pass or return multiple values together.\n// Access individual elements with '.0', '.1', etc.\n// ## Creating tuples\n// Write the elements in parentheses, separated by commas.\n// The compiler infers the element types from what you put in.\n// You can add an explicit type annotation when needed.\n// ## Accessing elements\n// Use '.0', '.1', '.2', ... to read individual elements.\n// ## Modifying elements\n// Tuple elements can be reassigned like ordinary variables.\n// ## Tuples as function parameters\n// Pass a tuple to a function by value (a copy) or by reference.\n// A value parameter gets its own copy — changes inside the function do not\n// affect the caller.\n// A reference parameter ('&') gives the function a direct link to the caller's\n// tuple so it can modify individual elements in place.\n// ## Returning tuples\n// A function can return a tuple to give back more than one value at once.\n// ## Destructuring\n// Assign a tuple to multiple names in one step using the '(a, b) = expr' form.\n// This is concise when a function returns a tuple and you need both values.\n// ## Three or more elements\n// Tuples can have any number of elements.\n\nfn min_max(lo: integer, hi: integer) -> (integer, integer) {\n  if lo <= hi {\n    (lo, hi)\n  } else {\n    (hi, lo)\n  }\n}\n\nfn swap_ints(pair: &(integer, integer)) {\n  tmp = pair.0;\n  pair.0 = pair.1;\n  pair.1 = tmp;\n}\n\nfn main() {\n  // ## Creating tuples\n  t = (10, 20);\n  assert(t.0 == 10, \"t.0: {t.0}\");\n  assert(t.1 == 20, \"t.1: {t.1}\");\n\n  // Type annotation\n  w: (integer, integer) = (3, 4);\n  assert(w.0 + w.1 == 7, \"annotated sum: {w.0+w.1}\");\n\n  // ## Modifying elements\n  v = (1, 2);\n  v.0 = 10;\n  assert(v.0 + v.1 == 12, \"after assign: {v.0}+{v.1}\");\n\n  // ## Tuples as value parameters\n  p = (10, 20);\n  sum = p.0 + p.1;\n  assert(sum == 30, \"sum: {sum}\");\n\n  // ## Tuples as reference parameters (swap in place)\n  pair = (3, 7);\n  swap_ints(pair);\n  assert(pair.0 == 7 && pair.1 == 3, \"after swap: ({pair.0},{pair.1})\");\n\n  // ## Returning a tuple from a function\n  bounds = min_max(5, 2);\n  assert(bounds.0 == 2, \"min: {bounds.0}\");\n  assert(bounds.1 == 5, \"max: {bounds.1}\");\n\n  // Already in order\n  bounds2 = min_max(1, 9);\n  assert(bounds2.0 == 1, \"min2: {bounds2.0}\");\n  assert(bounds2.1 == 9, \"max2: {bounds2.1}\");\n\n  // ## Destructuring\n  (lo, hi) = min_max(8, 3);\n  assert(lo == 3, \"destructured lo: {lo}\");\n  assert(hi == 8, \"destructured hi: {hi}\");\n\n  // ## Three or more elements\n  u = (1, 2, 3);\n  assert(u.0 + u.1 + u.2 == 6, \"triple sum: {u.0}+{u.1}+{u.2}\");\n\n  triple = (10, 20, 30);\n  triple.1 = 99;\n  assert(triple.0 == 10 && triple.1 == 99 && triple.2 == 30,\n    \"triple modified: ({triple.0},{triple.1},{triple.2})\");\n}",
"match": "// The `match` expression lets you compare a value against a series of patterns\n// and run different code for each case.  It is similar to `switch` in other\n// languages but more powerful: patterns can destructure structs, bind fields to\n// local variables, and include `if` guards.\n// Match is an expression — it returns a value, so you can assign the result\n// or use it directly inside a larger expression.\n// ## Simple enum matching\n// The most common use: branch on an enum variant.  Every variant must be covered\n// or a `_` wildcard must appear — the compiler checks exhaustiveness.\nenum Direction { North, South, East, West }\n\n// A struct-enum: its variants carry named fields, which a match arm can destructure.\nenum Shape {\n  Circle { radius: integer },\n  Rect { w: integer, h: integer },\n}\n\nfn direction_name(d: Direction) -> text {\n  match d {\n    North => \"north\",\n    South => \"south\",\n    East  => \"east\",\n    West  => \"west\",\n  }\n}\n\nfn main() {\n  assert(direction_name(North) == \"north\", \"simple enum match\");\n  assert(direction_name(West) == \"west\", \"west\");\n  // ## Match as expression\n  // Because match returns a value you can use it in assignments and arguments.\n  score = match Direction.East {\n    North | South => 10,\n    East | West   => 20,\n  };\n  assert(score == 20, \"match expression: {score}\");\n  // ## Struct-enum destructuring\n  // When an enum has variants with fields (a struct-enum) you can bind the\n  // fields to variables in the match arm.\n  //   Circle { radius } — binds the 'radius' field to a local variable\n  //   Rect { w, h }     — binds both 'w' and 'h'\n  // The variable names must match the field names exactly.\n  shape = Rect { w: 3, h: 4 };\n  shape_area = match shape {\n    Circle { radius } => radius * radius * 3,\n    Rect { w, h }     => w * h,\n  };\n  assert(shape_area == 12, \"struct-enum destructure: {shape_area}\");\n  // ## Guards\n  // Add `if condition` after a pattern to restrict when the arm matches.\n  // The guard can reference variables bound by the pattern.\n  v = 42;\n  label = match v {\n    0      => \"zero\",\n    _ if v < 0 => \"negative\",\n    _ if v > 100 => \"large\",\n    _      => \"normal\",\n  };\n  assert(label == \"normal\", \"guard: {label}\");\n  // ## Wildcard `_`\n  // The underscore `_` matches anything.  Put it last as a catch-all.\n  // Without it, the compiler will reject the match if any value could\n  // fall through without matching.\n  x = 7;\n  kind = match x {\n    1 => \"one\",\n    2 => \"two\",\n    _ => \"other\",\n  };\n  assert(kind == \"other\", \"wildcard: {kind}\");\n  // ## Integer matching\n  // Match works on integers — each arm is compared with `==`.\n  name = match 3 {\n    1 => \"one\",\n    2 => \"two\",\n    3 => \"three\",\n    _ => \"many\",\n  };\n  assert(name == \"three\", \"integer match: {name}\");\n  // ## Range patterns\n  // A numeric arm can match a whole inclusive range with `low..=high` — handy for\n  // grading, bucketing, or any \"is it in this band\" test.\n  grade = match 95 {\n    90..=100 => \"A\",\n    80..=89  => \"B\",\n    _        => \"lower\",\n  };\n  assert(grade == \"A\", \"range pattern: {grade}\");\n  // ## Null patterns\n  // When the subject is nullable, a `null` arm handles the absent case explicitly.\n  // With null-flow this is the idiomatic way to branch on a `T?` inside a match.\n  maybe: integer? = null;\n  presence = match maybe {\n    null => \"absent\",\n    0    => \"zero\",\n    _    => \"present\",\n  };\n  assert(presence == \"absent\", \"null pattern: {presence}\");\n  // ## Text matching\n  // Match also works on text values.\n  greeting = \"hi\";\n  reply = match greeting {\n    \"hello\" => \"formal\",\n    \"hi\"    => \"casual\",\n    _       => \"unknown\",\n  };\n  assert(reply == \"casual\", \"text match: {reply}\");\n  // ## Multiple patterns with `|`\n  // Combine patterns with `|` to share the same arm body.\n  d = Direction.South;\n  axis = match d {\n    North | South => \"vertical\",\n    East | West   => \"horizontal\",\n  };\n  assert(axis == \"vertical\", \"multi-pattern: {axis}\");\n  // ## Nested match\n  // Match can appear inside other expressions, including other match arms.\n  n = 15;\n  result = match n % 2 == 0 {\n    true  => \"even\",\n    false => match n % 3 == 0 {\n      true  => \"odd multiple of 3\",\n      false => \"odd\",\n    },\n  };\n  assert(result == \"odd multiple of 3\", \"nested: {result}\");\n}",
"formatting": "// Loft strings can embed expressions inside `{...}` braces.  A colon after\n// the expression introduces a format specifier that controls width, alignment,\n// precision, number base, and output style.\n// ## Basic interpolation\n// Any expression inside `{...}` is evaluated and converted to text.\nstruct Point { x: integer, y: integer }\n\n// A type that receives the PARTS of a format string. See the last section.\nstruct Query {\n  const parts: vector<text>,\n  const values: vector<text>,\n}\n\n// `lit` gets the bytes you wrote in the source file.\nfn lit(self: Query, s: text) { self.parts += [s]; }\n\n// `hole_text` gets an interpolated value. It is never added to `parts`.\nfn hole_text(self: Query, v: text?) { self.values += [v ?? \"\"]; }\n\nfn hole_int(self: Query, v: integer) { self.values += [\"{v}\"]; }\n\n// Show the two lists separately, so you can see what went where.\nfn shape(self: Query) -> text {\n  out = \"\";\n  for q_part in self.parts { out += \"<{q_part}>\" }\n  for q_val in self.values { out += \"[{q_val}]\" }\n  return out;\n}\n\nfn main() {\n  name = \"world\";\n  assert(\"hello {name}\" == \"hello world\", \"basic interpolation\");\n  assert(\"1 + 2 = {1 + 2}\" == \"1 + 2 = 3\", \"expression in braces\");\n  // ## Width and alignment\n  // A number after `:` sets the minimum width.  The value is padded with\n  // spaces to fill the width.\n  //   {val:6}   — right-aligned (default for numbers)\n  //   {val:>6}  — right-aligned (explicit)\n  //   {val:<6}  — left-aligned\n  //   {val:^6}  — centered\n  // For text, the default alignment is left.  For numbers, right.\n  assert(\"{42:6}\" == \"    42\", \"default number align is right\");\n  assert(\"{42:>6}\" == \"    42\", \"explicit right-align\");\n  assert(\"{42:<6}\" == \"42    \", \"left-align number\");\n  assert(\"{42:^6}\" == \"  42  \", \"center-align number\");\n  s = \"hi\";\n  assert(\"{s:6}\" == \"hi    \", \"default text align is left\");\n  assert(\"{s:>6}\" == \"    hi\", \"right-align text\");\n  assert(\"{s:^6}\" == \"  hi  \", \"center-align text\");\n  // ## Zero padding\n  // Prefix the width with `0` to pad with zeros instead of spaces.\n  assert(\"{7:03}\" == \"007\", \"zero-padded 3 digits\");\n  assert(\"{42:05}\" == \"00042\", \"zero-padded 5 digits\");\n  assert(\"{-1:04}\" == \"-001\", \"zero-padded negative: sign before zeros\");\n  // ## Signed format\n  // `+` forces a sign on positive numbers.\n  assert(\"{42:+}\" == \"+42\", \"explicit positive sign\");\n  assert(\"{-42:+}\" == \"-42\", \"negative sign always shown\");\n  assert(\"{0:+}\" == \"+0\", \"sign on zero\");\n  // ## Hexadecimal, binary, octal\n  // `:x` for lowercase hex, `:#x` for hex with `0x` prefix.\n  // `:b` for binary, `:o` for octal.\n  assert(\"{255:x}\" == \"ff\", \"hex lowercase\");\n  assert(\"{255:#x}\" == \"0xff\", \"hex with prefix\");\n  assert(\"{10:b}\" == \"1010\", \"binary\");\n  assert(\"{8:o}\" == \"10\", \"octal\");\n  // ## Float precision\n  // `.N` after the colon limits decimal places.\n  assert(\"{3.125:.1}\" == \"3.1\", \"1 decimal place\");\n  assert(\"{3.125:.2}\" == \"3.12\", \"2 decimal places\");\n  assert(\"{3.125:.0}\" == \"3\", \"0 decimal places\");\n  assert(\"{0.0:.3}\" == \"0.000\", \"trailing zeros\");\n  // ## Width + precision\n  // Combine width and precision: `{val:W.P}` where W is total width\n  // and P is decimal places.\n  assert(\"{3.125:8.2}\" == \"    3.12\", \"width 8 precision 2\");\n  assert(\"{-3.125:8.2}\" == \"   -3.12\", \"negative width+precision\");\n  // ## JSON format\n  // `:j` serialises a struct or value as JSON.\n  // `:j` serialises a struct as JSON.  Use it on struct values, not primitives.\n  // See the JSON documentation page for full details.\n  // ## Vector format\n  // Vectors are formatted as `[a,b,c]` by default.\n  // A format specifier inside a `for` loop applies to each element.\n  v = [1, 2, 3];\n  assert(\"{v}\" == \"[1,2,3]\", \"default vector format\");\n  assert(\"{for fmt_n in 1..4 {fmt_n * 10}:04}\" == \"[0010,0020,0030]\", \"formatted vector elements\");\n  // ## Large integers and single-precision floats\n  // `integer` is a 64-bit type, so even large values format like any other\n  // number; single-precision floats use the same specifiers too.\n  n = 1000000;\n  assert(\"{n}\" == \"1000000\", \"integer default\");\n  assert(\"{n:>10}\" == \"   1000000\", \"integer right-aligned\");\n  f = 1.5f;\n  assert(\"{f}\" == \"1.5\", \"single default\");\n  // ## Pretty-printing a struct\n  // The `:#` specifier expands a struct across a spaced, readable layout\n  // instead of the compact default form.\n  p = Point { x: 1, y: 2 };\n  assert(\"{p}\" == \"{{x:1,y:2}}\", \"default struct format is compact\");\n  assert(\"{p:#}\" == \"{{ x: 1, y: 2 }}\", \"`:#` pretty-prints with spaces\");\n  // ## Character format\n  c = 'A';\n  assert(\"{c}\" == \"A\", \"character default\");\n  // ## Boolean format\n  assert(\"{true}\" == \"true\", \"boolean true\");\n  assert(\"{false}\" == \"false\", \"boolean false\");\n  // ## Building a value instead of text\n  // Everything above joins the pieces into one `text`.  When the type you\n  // assign to says so, the format string **builds that type instead**, and the\n  // type is told which bytes you wrote and which came from a value.\n  //\n  // A type opts in by defining `lit` (for your bytes) and one `hole_…` method\n  // per value kind it accepts: `hole_text`, `hole_int`, `hole_float`,\n  // `hole_single`, `hole_boolean`, `hole_character`.  There is no new syntax —\n  // the type you assign to decides — and plain `text` is unchanged.\n  who = \"ada\";\n  q: Query = \"SELECT * FROM t WHERE name = {who}\";\n  // The text you wrote is in `parts`; the value is in `values`, never in the\n  // text.  That separation is the point: a value cannot turn into syntax,\n  // because the only way into the text is `lit`, and `lit` only ever receives\n  // bytes from your source file.\n  assert(q.shape() == \"<SELECT * FROM t WHERE name = >[ada]\",\n         \"the literal and the value stay apart\");\n  // The value can be anything at all, including text that would otherwise\n  // change the meaning of the statement.  It is still just a value.\n  danger = \"'; DROP TABLE t; --\";\n  q2: Query = \"WHERE name = {danger}\";\n  assert(q2.shape() == \"<WHERE name = >['; DROP TABLE t; --]\",\n         \"a value that looks like syntax is still a value\");\n  // Each kind goes to its own method, so the type sees the real type.\n  q3: Query = \"id={7} name={who}\";\n  assert(q3.shape() == \"<id=>< name=>[7][ada]\", \"an integer hole calls hole_int\");\n  // The database clients use this, so a query needs no placeholders to count:\n  //     q: SqlText = \"SELECT id FROM users WHERE name = {name}\";\n  //     db.db_rows(q)\n}",
"reference_parameter_forwarding": "// When a function receives a `&Struct` (mutable reference) parameter and\n// passes it to another function that also takes `&Struct`, the reference\n// must be forwarded without dereferencing. This is P144.\nuse p144_entry;\n\nfn main() {\n  // box_set_val calls box_ensure(b) internally — forwarding the & param.\n  b = Box { items: [] };\n  box_set_val(b, 42);\n  assert(b.items[0].val == 42, \"P144: & forwarded — item set to 42\");\n\n  // Calling the inner function directly also works.\n  b2 = Box { items: [] };\n  box_ensure(b2);\n  assert(len(b2.items) == 1, \"ensure added one item\");\n  assert(b2.items[0].val == 0, \"default val is 0\");\n\n  // Multiple forwards: ensure is idempotent.\n  box_ensure(b2);\n  assert(len(b2.items) == 1, \"ensure idempotent\");\n\n  // Set a second value via box_set_val on a pre-populated box.\n  b3 = Box { items: [] };\n  b3.items += [Inner { val: 10 }];\n  b3.items += [Inner { val: 0 }];\n  box_set_val(b3, 99);\n  assert(b3.items[0].val == 10, \"existing item preserved\");\n  assert(b3.items[1].val == 99, \"zero item replaced\");\n}",
"feature_catalogue": "// GENERATED by tools/features/gen.loft — DO NOT EDIT.\n//\n// Everything loft can do, in one list.  Each entry has a page of its own with\n// what it is, how it aids you, and a runnable example — see `doc/features/` in\n// the repository, where `@F2` is `F2.md`.\n//\n// The catalogue is generated from the `loft-lang/features` issue tracker, which\n// is the single source of truth: every entry is an issue, so nothing here can\n// drift from what was decided without the drift guard failing.\n//\n// ## Language features\n//\n// - **@F1** — Nullable value semantics — in-band sentinels + null-fallback arithmetic\n// - **@F2** — `??` null-coalescing operator (incl. `?? return`)\n// - **@F3** — Primitive scalar types (integer, float, single, boolean, character)\n// - **@F4** — Ranged/width integer types (u8/i8/u16/i16/i32/u32)\n// - **@F5** — Type conversions — implicit, format-only, and explicit `as`\n// - **@F6** — `vector<T>` — append, index, slice, comprehensions, aggregates, map/filter/reduce\n// - **@F7** — `hash<T[keys]>` keyed collection\n// - **@F8** — `sorted<T[keys]>` collection\n// - **@F9** — `index<T[keys]>` B-tree index (asc/desc, multi-key)\n// - **@F10** — `iterator<T>` values\n// - **@F11** — Tuples — anonymous fixed-arity `(T1, T2, …)`\n// - **@F12** — Struct records — fields, `= default`, `computed`, `limit`/`not null`/`assert`\n// - **@F13** — Simple enums (ordered value types)\n// - **@F14** — Polymorphic struct-enums (per-variant fields)\n// - **@F15** — Enum-scoped variant names + context inference\n// - **@F16** — Functions & declarations (`pub`, parameters, return)\n// - **@F17** — Named arguments + default parameter values\n// - **@F18** — `const` parameters\n// - **@F19** — Method dispatch via `self` / `both`\n// - **@F20** — Variant-based dynamic dispatch\n// - **@F21** — References `&T` — parameters + write-back bindings\n// - **@F22** — Closures & lambdas (value capture, cross-scope)\n// - **@F23** — Function references as first-class values\n// - **@F24** — Higher-order functions (map / filter / reduce)\n// - **@F25** — Generics — single type variable `<T>`, inferred\n// - **@F26** — Interfaces & bounded generics (`<T: A + B>`, operator interfaces)\n// - **@F27** — `if` / `else` as an expression\n// - **@F28** — `for`-in loops — ranges, loop attributes, filtered, `rev()`\n// - **@F29** — Pattern matching — enum/scalar/tuple, guards, or-patterns, exhaustiveness\n// - **@F30** — `is` variant check (+ field capture)\n// - **@F31** — `break` / `continue` + labelled forms\n// - **@F32** — Custom iterators via `fn next(self) -> T?`\n// - **@F33** — `par(...)` parallel for-loop\n// - **@F34** — Coroutines / generators — `yield`, `yield from`\n// - **@F35** — String literals — `{expr}` interpolation + backtick multiline\n// - **@F36** — String formatting / format specifiers (+ for-expressions)\n// - **@F37** — Operator set — arithmetic/comparison/logical/bitwise/unary, `**`\n// - **@F38** — Arithmetic safety — overflow/÷0 → null, nullable peers\n// - **@F39** — Math & trigonometry library\n// - **@F40** — File & directory I/O (+ durable-store binding)\n// - **@F41** — Environment & arguments (env vars, arguments(), program dirs, path resolution)\n// - **@F42** — JSON — json_parse, JsonValue, Type.parse, to_json\n// - **@F43** — Random numbers (rand_seed / rand / rand_indices)\n// - **@F44** — Logging & diagnostics API (log_*, print, assert, panic)\n// - **@F45** — `sizeof()`\n// - **@F46** — Type aliases (`type X = …`)\n// - **@F47** — Library imports / module system (`use` forms, `pub`)\n// - **@F48** — The `loft` CLI — run a program, `--interpret` / `--native`, `--timeout`, `--help`\n// - **@F49** — REPL — interactive sessions\n// - **@F50** — Introspection — `loft introspect` (bytecode / native Rust / slot tables)\n// - **@F51** — Debugger — breakpoints, frame capture, scripted RPC\n// - **@F52** — Source formatter — canonical `.loft` output\n// - **@F53** — Native-binary backend (`--native` → rustc)\n// - **@F54** — Browser / WASM target (`--html` / `--native-wasm`)\n// - **@F55** — Package management (`loft install`, `loft.toml`, lockfile)\n// - **@F56** — Live code reload — patch a running program\n// - **@F88** — Stack traces (stack_trace)\n// - **@F89** — Test runner (fn test_*, loft --tests / loft test)\n// - **@F92** — Direct C binding — `#c \"symbol\" \"signature\"`, no rustc and no glue crate\n// - **@F93** — Paged & remote store loading — read part of a dataset over HTTP range\n// - **@F94** — Type-directed interpolation — a type receives the literal/hole boundary\n// - **@F95** — Value structs (`value struct`) — copy semantics, stored inline\n// - **@F96** — `x?` default-fallback operator — discharge a nullable to its type default\n// - **@F97** — `len` vs `size` — logical count vs bytes occupied\n// - **@F98** — `spatial<T[x,y]>` — position-keyed collection for proximity queries\n// - **@F99** — Sequence match patterns — alternation, optionals, repetition, capture\n// - **@F100** — Dead-code lint — a local never read, and a write whose value is lost\n// - **@F101** — The build phase — `loft build`, declared targets, zero-config defaults\n// - **@F102** — Android target — `--native-android`, APK packaging, GL surface and touch input\n// - **@F103** — `deliver` / `expose` — hand a loft value to JavaScript with no copy\n// - **@F104** — `store_reclaim()` — give a store's unused file space back\n// - **@F105** — Custom `to_text` format hook — a type owns how it prints\n// - **@F106** — Copy and move semantics — when two names share data, and when they do not\n// - **@F107** — Type reflection — the declared shape of a type, as data\n// - **@F108** — Lazy store binding — a collection fetches on a miss\n// - **@F109** — `#superseded` — steer callers to a newer form without breaking the old one\n// - **@F110** — Diagnostic suggestions — what to write instead, checked by running it\n// - **@F111** — `for f in s#fields` — a compile-time loop over a struct's scalar fields\n// - **@F112** — `store_release()` — say a record is finished, and stop holding it in memory\n// - **@F113** — Associated types — an interface names a companion type\n// - **@F114** — `x[i]` on a library type — `OpIndex` dispatch\n// - **@F115** — `OpDrop` — a type runs code when its scope lets it die\n//\n// ## Tooling and infrastructure\n//\n// - **@I57** — Lexer\n// - **@I58** — Parser (two-pass recursive descent)\n// - **@I59** — Type resolver\n// - **@I60** — Scope & dependency/lifetime tracker (deps)\n// - **@I61** — Stack slot allocator\n// - **@I62** — IR data model (Value/Type/Data)\n// - **@I63** — Store-resident IR (reader + handle + materializer)\n// - **@I64** — Bytecode compiler (IR -> bytecode)\n// - **@I65** — Bytecode code generator\n// - **@I66** — Bytecode VM / executor\n// - **@I67** — Opcode implementations\n// - **@I68** — Native Rust generator\n// - **@I69** — Word-addressed store\n// - **@I70** — Database — alloc / persistence / journal / snapshot / schema\n// - **@I71** — DbRef pointers & collection keys\n// - **@I72** — Parallel execution runtime\n// - **@I73** — Native function registry\n// - **@I74** — CDylib extension loader\n// - **@I75** — Diagnostics collector\n// - **@I76** — Logger runtime\n// - **@I77** — Registry / manifest / lockfile resolution\n// - **@I78** — Live-reload dispatch\n// - **@I79** — Documentation generator (maintainer tooling)\n// - **@I80** — Tracker indexer (maintainer tooling)\n// - **@I81** — Feature-catalogue sync generator (issues → in-project mirror + example tests)\n// - **@I82** — Sandbox policy & enforcement\n// - **@I83** — Dev server (--serve / --rpc)\n// - **@I84** — Coroutine runtime / yield codec\n// - **@I85** — Engine-host kernel natives\n// - **@I86** — Startup cache & embedded stdlib\n// - **@I87** — Auto-use / lazy library triggers\n// - **@I90** — Shared utilities & data structures\n// - **@I91** — Editor tooling: language server (LSP), debug adapter (DAP), resolution index\n// - **@I116** — Library placement — in-process, a worker, or another machine\n// - **@I117** — Git query natives — a repository as a typed library, not a subprocess\n\nfn main() {\n  println(\"the feature catalogue is generated from the issue tracker\");\n}",
"running_your_program": "// The pages before this one show how to WRITE loft. This one shows how to RUN it.\n// You need one command to start, and everything else is optional.\n// ## Run a file\n// Put your program in a file ending in '.loft' and pass it to loft:\n//\n//     $ loft hello.loft\n//     hello, world!\n//\n// That is the whole thing. There is no build step to run first and no project\n// to set up. A single file is a complete program.\n// ## Give your program some arguments\n// Put them after the file name, and declare one `vector<text>` parameter on 'main'\n// to read them:\n//\n//     fn main(args: vector<text>) {\n//       for who in args { println(\"hello, {who}!\"); }\n//     }\n//\n//     $ loft greet.loft Ada Grace\n//     hello, Ada!\n//     hello, Grace!\n//\n// That one parameter is the only shape 'main' accepts. Any other — a plain 'text',\n// two of them — is refused, because nothing would fill it.\n//\n// ## Try something without making a file\n// Type 'loft' on its own and you get a prompt where you can type one line at a\n// time and see the answer straight away:\n//\n//     $ printf '2 + 3\\n' | loft repl --fresh\n//     5\n//\n// Typed by hand it looks like this — start it, then type at the prompt:\n//\n//     loft\n//     loft> 2 + 3\n//     5\n//\n// This is called a REPL, which is short for \"read, evaluate, print, loop\".\n// It is the quickest way to check what a function does or try an idea.\n// Your session is remembered, so you can close it and come back later —\n// '--fresh' is how you ask for a clean one instead.\n// ## Two ways to run, and why you usually ignore this\n// loft can run your program in two ways. It compiles your program to a fast\n// program first when it can, and otherwise it reads and runs your program\n// directly. The second way is called interpreting.\n//\n// You do not have to choose. loft picks for you, and the ANSWER is the same\n// either way — that is a rule the language holds itself to, not a hope.\n// You can ask for one on purpose when you want to:\n//\n//     $ loft --interpret hello.loft\n//     hello, world!\n//\n// A downloaded loft always interprets. That is normal and not something to fix.\n// ## Stop a program that runs too long\n// A loop with a mistake in it can run forever. Give loft a time limit and it\n// stops the program for you:\n//\n//     $ loft --timeout 10 hello.loft\n//     hello, world!\n//\n// This is worth using whenever you run something for the first time.\n// ## Check your work without running it\n// Sometimes you only want to know whether the program is correct so far:\n//\n//     $ loft check hello.loft\n//     ok\n//\n// This reports mistakes and runs nothing. It is fast, and it is a good habit\n// while you are still writing.\n// ## When loft tells you something is wrong\n// A message from loft names the file, the line, and what to do. Some messages\n// can also show you the exact replacement to write:\n//\n//     $ loft --explain --interpret hello.loft\n//     hello, world!\n//\n// That prints the suggested fix under each message. It only shows you the fix;\n// it changes nothing, so it is always safe to run.\n\nfn main() {\n  // A program is just a file with a `main` function in it, like this one.\n  // Everything above is how you would run this file.\n  greeting = \"hello\";\n  who = \"world\";\n  message = \"{greeting}, {who}!\";\n  assert(message == \"hello, world!\", \"string interpolation builds the message\");\n  println(message);\n}",
"testing_your_code": "// A test is a function that checks your code still does what you meant.\n// You do not install anything to write one, and there is no special syntax.\n// ## Write a test\n// Give a function a name starting with 'test' and put an 'assert' in it.\n// That is all a test is:\n//\n//     fn double(n: integer) -> integer { n * 2 }\n//\n//     fn test_double_doubles() {\n//       assert(double(4) == 8, \"double(4) should be 8\");\n//     }\n//\n// 'assert' takes something that should be true, and a message. If it is true,\n// nothing happens. If it is not, the message is what you will read, so write\n// the message for the person who has to fix it — usually you, later.\n// ## Run your tests\n// Point loft at the file:\n//\n//     $ loft --tests calc.loft\n//     test result: ok. 2 passed; 1 file\n//\n// and it finds every 'test' function and runs it, naming the file and the\n// functions it found.\n//\n// Give it a directory instead of a file and it looks in every '.loft' file\n// underneath. Give it nothing and it starts from where you are:\n//\n//     $ loft --tests calc.loft::test_double_doubles\n//     test result: ok. 1 passed; 1 file\n//\n// ## Run just one test\n// While you are fixing one thing, run only that one. Put '::' and the test's\n// name after the file:\n//\n//     $ loft --tests calc.loft::test_double_of_zero\n//     test result: ok. 1 passed; 1 file\n//\n// ## When a test fails\n// A failure names the test and shows your message:\n//\n//     FAIL  calc.loft::test_that_fails  —  assertion failed: arithmetic still works\n//     test result: FAILED. 1 failed; 0 passed; 1 total; 1 file\n//\n// The message is the part you wrote, which is why a vague message like \"it\n// works\" costs you time and a specific one saves it.\n// ## Read the line after the result\n// The end of the report says what the run did NOT do, in square brackets —\n// for example that it ran on the interpreter and did not try the compiled\n// build. That is deliberate. A run that says only \"ok\" cannot tell you\n// whether the other half was checked or never ran at all.\n//\n// To also run your tests the compiled way:\n//\n//     $ loft --tests --native calc.loft\n//     test result: ok. 2 passed; 1 file\n//\n// ## Once you have a project\n// When your code grows into a project with a 'loft.toml' file (the next page),\n// tests live in a 'tests/' folder and you run them with:\n//\n//     $ cd greeter && loft test\n//     test result: ok. 1 passed; 1 file\n\nfn double(n: integer) -> integer { n * 2 }\n\n// This page is itself run as a test, so the example below really does pass.\nfn main() {\n  assert(double(4) == 8, \"double(4) should be 8\");\n  assert(double(0) == 0, \"double(0) should be 0\");\n  // An assert that holds produces no output at all — silence is success.\n  println(\"both checks passed\");\n}",
"debugging": "// When a program does the wrong thing, the usual reaction is to add printing to\n// it, run it, read the output, and take the printing out again. loft gives you a\n// better tool: stop the program on the line you care about and look around.\n//\n// The program used below is 'count.loft'. It adds 1, 2 and 3 into a total.\n// ## Stop on a line\n// Say 'debug', then your file, then a colon and a line number:\n//\n//     $ printf ':continue\\n' | loft debug count.loft:4\n//     paused in main | total = 0, i = 1\n//\n// The program runs until it reaches line 4 and then waits for you. The line it\n// prints tells you where you are and what every local variable holds right now.\n//\n// Line 4 is inside a loop that goes round three times, so the program stops\n// there three times. ':continue' means \"carry on until you reach this line\n// again\", not \"run to the end\" — which is why the examples below say\n// ':continue' more than once when they want the program to finish.\n// ## Look at a value\n// Type the name of a variable and press enter. Any expression works, not just a\n// name — it is worked out where the program is paused:\n//\n//     $ printf 'total\\n:continue\\n:continue\\n:continue\\n' | loft debug count.loft:4\n//     0\n//\n// This is the part that replaces printing. You do not have to guess in advance\n// which values you will want; ask for them when you are there.\n// ## Move one step at a time\n// Four commands move the program forward:\n//\n// - ':step' runs the next line, going INTO any function it calls\n// - ':next' runs the next line, going OVER any function it calls\n// - ':finish' runs until the current function returns\n// - ':continue' carries on to the next time this line is reached\n//\n//     $ printf ':step\\ntotal\\n:continue\\n:continue\\n:continue\\n' | loft debug count.loft:4\n//     1\n//\n// After that single ':step' the total is 1, because the loop has now added its\n// first number. Each stop prints the same \"paused\" line, so you can watch a\n// value change as the loop goes round.\n// ## Change a value while it is running\n// You can write to a local, not only read it. This answers \"would it work if\n// this were right?\" without editing the file and starting again:\n//\n//     $ printf 'total = 100\\n:continue\\n:continue\\n:continue\\n' | loft debug count.loft:4\n//     total=106\n//     run finished\n//\n// The program carries on with the value you gave it. It finished with 106\n// instead of 6, because the loop still had 2 and 3 to add after the change.\n// ## Getting out\n// ':continue' carries on. ':quit' stops right away. ':help' lists every command\n// if you forget one.\n// ## Typing, or feeding it a script\n// Every example here pipes its commands in, which is how they are checked\n// automatically — the output you see above is compared against what the command\n// really prints. Run 'loft debug count.loft:4' on its own and you get the\n// '(dbg)' prompt to type at instead. The commands are the same either way.\n\nfn main() {\n  // This is what `count.loft` does — the program the examples above debug.\n  total = 0;\n  for i in 1..4 {\n    total += i;\n  }\n  assert(total == 6, \"1 + 2 + 3 is 6, which is what the debugger shows you\");\n  println(\"total={total}\");\n}",
"projects_and_libraries": "// One file is a complete loft program, and for a long time that is all you need.\n// When you want to share code between programs, or keep tests beside it, you\n// turn the folder into a package.\n// ## What a package looks like\n// A package is a folder with a 'loft.toml' file in it and two sub-folders:\n//\n//     greeter/\n//       loft.toml          what this package is called\n//       src/greeter.loft   the code\n//       tests/greet.loft   the tests\n//\n// 'src' is where your code lives and 'tests' is where your tests live. The\n// names matter — loft looks in exactly those places.\n// ## The manifest\n// 'loft.toml' names the package and says which file is its front door:\n//\n//     [package]\n//     name    = \"greeter\"\n//     version = \"0.1.0\"\n//\n//     [library]\n//     entry = \"src/greeter.loft\"\n//\n// The 'entry' file is the one that other code sees. Anything you want to share\n// from it is marked 'pub':\n//\n//     pub fn greet(who: text) -> text { \"hello, {who}!\" }\n//\n// Without 'pub' a function is private to the package, which is the default.\n// ## Testing a package\n// Inside the package folder, 'loft test' finds and runs everything in 'tests':\n//\n//     $ cd greeter && loft test\n//     test result: ok. 1 passed; 1 file\n//\n// The tests reach your code by importing the package by name:\n//\n//     use greeter::*;\n//     fn test_greet_names_the_person() {\n//       assert(greet(\"Ada\") == \"hello, Ada!\", \"greet builds the sentence\");\n//     }\n//\n// 'use greeter::*;' brings in everything public. Write 'use greeter;' instead\n// and you call it as 'greeter::greet(...)', which is longer but says where each\n// name came from — useful once you import several packages.\n// ## Running one test while you work\n// Give 'loft test' the file, or the file and one function:\n//\n//     $ cd greeter && loft test greet\n//     test result: ok. 1 passed; 1 file\n//\n// ## Check it compiles, without running anything\n// Inside the package, 'loft check' compiles everything and reports problems:\n//\n//     $ cd greeter && loft check\n//     loft build: `native` ✓\n//\n// A package that is only a library has no program to start, so there is nothing\n// to run — 'check' still tells you the code compiles, which is what you wanted\n// to know.\n// ## Coverage — what the tests did not reach\n// After the result, 'loft test' tells you which of your functions no test ever\n// entered:\n//\n//     $ cd greeter && loft test\n//     coverage: all 1 functions were entered by these tests\n//\n// It is a list, never a percentage and never a gate. A percentage becomes a\n// target, and tests written to move a number check nothing.\n// ## Using someone else's package\n// Add it to the manifest under '[dependencies]' and install:\n//\n//     [dependencies]\n//     math = \">=0.1\"\n//\n//     loft install\n//\n// Then 'use math;' in your code. 'loft install' also writes a lock file that\n// records the exact versions, so the same code builds the same way later.\n\nfn main() {\n  // The package these examples describe is `greeter`, and this is its one\n  // function — a `pub fn` in `src/greeter.loft` that its tests import.\n  greeting = \"hello, Ada!\";\n  assert(greeting == \"hello, Ada!\", \"what greet(\\\"Ada\\\") returns\");\n  println(greeting);\n}",
"call_it_yourself": "// Every other page here shows you loft.  This one hands it to you.\n// The functions below are compiled and live in the panel at the bottom of the\n// page: type a call, press enter, and loft answers.  Nothing is a transcript —\n// the number you see is the one your browser just computed.\n// ## What to try first\n// `fib(10)` is the shortest way to be sure the panel is real.  Change the 10 and\n// the answer changes; ask for `fib(30)` and you will wait a moment, because this\n// is the naive recursion and it really does make that many calls.\nfn fib(n: integer) -> integer {\n  if n < 2 {\n    return n;\n  }\n  fib(n - 1) + fib(n - 2)\n}\n\n// ## Numbers with a shape\n// `nth_prime(1)` is 2, `nth_prime(10)` is 29.  Try to guess `nth_prime(100)`\n// before you ask for it — the primes thin out faster than most people expect.\nfn is_prime(n: integer) -> boolean {\n  if n < 2 {\n    return false;\n  }\n  d = 2;\n  while d * d <= n {\n    if n % d == 0 {\n      return false;\n    }\n    d += 1;\n  }\n  true\n}\n\nfn nth_prime(n: integer) -> integer {\n  found = 0;\n  candidate = 1;\n  while found < n {\n    candidate += 1;\n    if is_prime(candidate) {\n      found += 1;\n    }\n  }\n  candidate\n}\n\n// ## Text goes in\n// `vowels(\"your name here\")` counts the vowels in whatever you type.  The\n// argument is a text and the answer is a number, which is the shape the panel\n// renders today — see the note at the end of the page.\nfn vowels(s: text) -> integer {\n  n = 0;\n  for c in s {\n    if c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' {\n      n += 1;\n    }\n  }\n  n\n}\n\n// ## A struct comes back\n// `stats(3, 17)` answers `{\"lo\":3,\"hi\":17,\"span\":14}` — a whole record, rendered\n// as JSON, from one call.  Give it the arguments in the wrong order and it still\n// answers correctly, which is the point of it.\nstruct Span {\n  lo: integer,\n  hi: integer,\n  span: integer,\n}\n\nfn stats(a: integer, b: integer) -> Span {\n  lo = if a < b { a } else { b };\n  hi = if a < b { b } else { a };\n  Span { lo: lo, hi: hi, span: hi - lo }\n}\n\n// ## Pausing inside a run\n// The panel can also stop the program mid-flight.  Click a line number in the\n// code above to set a breakpoint, press Run, and the panel lists the variables\n// that line can see — then the same prompt evaluates against THAT frame, so a\n// call like `fib(step)` uses the `step` the paused function is holding.\nfn walk_to(limit: integer) -> integer {\n  total = 0;\n  step = 0;\n  while step < limit {\n    step += 1;\n    total += fib(step);\n  }\n  total\n}\n\n// ## What the panel cannot do yet\n// An expression whose value is a text or a vector answers `<unavailable>` rather\n// than a value: the browser evaluator reads a result off the paused frame, and\n// only a number, a character, a boolean or a struct survives that trip\n// (loft#1187).  So `vowels(\"hello\")` answers 2 and `stats(1, 9)` answers a\n// record, while a function returning a text does not — which is why every\n// function on this page hands back one of the shapes that works.\nfn main() {\n  // The demonstration comes first and the checks follow it, so a reader who presses\n  // Run sees an answer straight away — the panel stops on main's LAST line, and a\n  // program whose only print IS that line would pause with nothing shown yet.\n  print(\"fib(10)={fib(10)} nth_prime(10)={nth_prime(10)} vowels(\\\"hello\\\")={vowels(\\\"hello\\\")}\\n\");\n  // The page is a real program, so these run on both backends like every other page\n  // here, and an example that stops being true stops compiling.\n  assert(fib(10) == 55, \"fib(10)\");\n  assert(fib(1) == 1 && fib(0) == 0, \"fib base cases\");\n  assert(nth_prime(1) == 2, \"the first prime is 2\");\n  assert(nth_prime(10) == 29, \"the tenth prime is 29\");\n  assert(!is_prime(1) && is_prime(2) && !is_prime(9), \"is_prime edges\");\n  assert(vowels(\"hello\") == 2, \"hello has two vowels\");\n  assert(vowels(\"\") == 0, \"no text, no vowels\");\n  s = stats(17, 3);\n  assert(s.lo == 3 && s.hi == 17 && s.span == 14, \"stats orders its arguments\");\n  // fib(1..4) is 1 + 1 + 2 + 3.\n  assert(walk_to(4) == 7, \"walk_to sums the first four\");\n}",
};
